insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-001', (select id from leyes where slug = 'constitucion'), '1.1', '¿Cuál de los siguientes NO es uno de los valores superiores del ordenamiento jurídico que propugna la Constitución?', array['La libertad', 'La justicia', 'La solidaridad', 'El pluralismo político']::text[], 2, 'La solidaridad no figura entre los valores superiores. El artículo 1.1 enumera cuatro: «la libertad, la justicia, la igualdad y el pluralismo político». La solidaridad aparece en el artículo 2, referida a las nacionalidades y regiones.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-002', (select id from leyes where slug = 'constitucion'), '1.2', 'Según la Constitución, ¿en quién reside la soberanía nacional?', array['En las Cortes Generales', 'En el pueblo español', 'En la Nación española', 'En el Rey, como Jefe del Estado']::text[], 1, 'El artículo 1.2 lo dice de forma literal: «La soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado». Las Cortes Generales representan al pueblo español (art. 66.1), pero no son las titulares de la soberanía.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-003', (select id from leyes where slug = 'constitucion'), '1.3', '¿Cuál es la forma política del Estado español según la Constitución?', array['Monarquía constitucional', 'Estado autonómico', 'Estado social y democrático de Derecho', 'Monarquía parlamentaria']::text[], 3, 'El artículo 1.3 establece: «La forma política del Estado español es la Monarquía parlamentaria». «Estado social y democrático de Derecho» es como se constituye España (art. 1.1), no su forma política.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-004', (select id from leyes where slug = 'constitucion'), '2', 'La Constitución reconoce y garantiza el derecho a la autonomía de:', array['Las nacionalidades y regiones que integran la Nación española', 'Las comunidades autónomas y los municipios', 'Las provincias y las regiones', 'Los pueblos y nacionalidades de España']::text[], 0, 'El artículo 2 «reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que la integran y la solidaridad entre todas ellas». La autonomía de municipios y provincias se regula aparte, en el artículo 137.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-005', (select id from leyes where slug = 'constitucion'), '3.1', 'Respecto al castellano, la Constitución establece que todos los españoles tienen:', array['El derecho a conocerlo y el deber de usarlo', 'El deber de conocerlo y de usarlo', 'El derecho a conocerlo y a usarlo', 'El deber de conocerlo y el derecho a usarlo']::text[], 3, 'El artículo 3.1 dice: «El castellano es la lengua española oficial del Estado. Todos los españoles tienen el deber de conocerla y el derecho a usarla». Conocerla es un deber; usarla, un derecho.', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-006', (select id from leyes where slug = 'constitucion'), '4.1', 'Según la Constitución, en la bandera de España la franja amarilla es:', array['De la misma anchura que cada una de las rojas', 'De doble anchura que cada una de las rojas', 'De triple anchura que cada una de las rojas', 'De la misma anchura que las dos rojas juntas']::text[], 1, 'El artículo 4.1 describe la bandera con «tres franjas horizontales, roja, amarilla y roja, siendo la amarilla de doble anchura que cada una de las rojas».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
