insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-007', (select id from leyes where slug = 'constitucion'), '8.1', 'Según el artículo 8.1 de la Constitución, las Fuerzas Armadas están constituidas por:', array['El Ejército de Tierra, la Armada, el Ejército del Aire y la Guardia Civil', 'El Ejército de Tierra, la Armada, el Ejército del Aire y la Unidad Militar de Emergencias', 'El Ejército de Tierra, la Armada y el Ejército del Aire', 'El Ejército de Tierra, la Armada, el Ejército del Aire y las Fuerzas y Cuerpos de Seguridad del Estado']::text[], 2, 'El artículo 8.1 dice: «Las Fuerzas Armadas, constituidas por el Ejército de Tierra, la Armada y el Ejército del Aire, tienen como misión garantizar la soberanía e independencia de España, defender su integridad territorial y el ordenamiento constitucional». La Guardia Civil forma parte de las Fuerzas y Cuerpos de Seguridad (art. 104).', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-007', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-008', (select id from leyes where slug = 'constitucion'), '9.3', '¿Cuál de los siguientes principios NO aparece entre los que garantiza el artículo 9.3 de la Constitución?', array['La publicidad de las normas', 'La interdicción de la arbitrariedad de los poderes públicos', 'La irretroactividad de las disposiciones sancionadoras no favorables', 'La eficacia de la Administración']::text[], 3, 'La eficacia es un principio de actuación de la Administración recogido en el artículo 103.1, no en el 9.3. El artículo 9.3 garantiza «el principio de legalidad, la jerarquía normativa, la publicidad de las normas, la irretroactividad de las disposiciones sancionadoras no favorables o restrictivas de derechos individuales, la seguridad jurídica, la responsabilidad y la interdicción de la arbitrariedad de los poderes públicos».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
