insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-009', (select id from leyes where slug = 'constitucion'), '12', '¿A qué edad son mayores de edad los españoles según la Constitución?', array['A los dieciocho años', 'A los dieciséis años', 'A los diecisiete años', 'A los veintiún años']::text[], 0, 'El artículo 12 lo fija directamente: «Los españoles son mayores de edad a los dieciocho años».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
