insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-010', (select id from leyes where slug = 'constitucion'), '15', 'Según el texto del artículo 15 de la Constitución, queda abolida la pena de muerte:', array['Sin excepción alguna', 'Salvo en los supuestos de estado de sitio', 'Salvo lo que dispongan los tratados internacionales ratificados por España', 'Salvo lo que puedan disponer las leyes penales militares para tiempos de guerra']::text[], 3, 'El artículo 15 dice: «Queda abolida la pena de muerte, salvo lo que puedan disponer las leyes penales militares para tiempos de guerra». La pregunta se refiere al texto constitucional; otra cosa es que la ley penal militar ya no la contemple.', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
