insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-011', (select id from leyes where slug = 'constitucion'), '17.2', '¿Cuál es el plazo máximo de la detención preventiva según la Constitución?', array['Veinticuatro horas', 'Cuarenta y ocho horas', 'Setenta y dos horas', 'Noventa y seis horas']::text[], 2, 'Según el artículo 17.2, la detención preventiva no puede durar más de lo estrictamente necesario «y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
