insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-012', (select id from leyes where slug = 'constitucion'), '17.4', '¿Qué procedimiento prevé la Constitución para poner de inmediato a disposición judicial a toda persona detenida ilegalmente?', array['El recurso de amparo', 'El «habeas corpus»', 'El «habeas data»', 'El procedimiento preferente y sumario']::text[], 1, 'El artículo 17.4 dispone: «La ley regulará un procedimiento de “habeas corpus” para producir la inmediata puesta a disposición judicial de toda persona detenida ilegalmente».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-013', (select id from leyes where slug = 'constitucion'), '21.2', 'Para celebrar una manifestación o una reunión en un lugar de tránsito público, la Constitución exige:', array['Comunicación previa a la autoridad', 'Autorización previa de la autoridad', 'Autorización judicial', 'Comunicación a la autoridad dentro de las 48 horas siguientes']::text[], 0, 'El artículo 21.2 dice: «En los casos de reuniones en lugares de tránsito público y manifestaciones se dará comunicación previa a la autoridad, que sólo podrá prohibirlas cuando existan razones fundadas de alteración del orden público, con peligro para personas o bienes». No se pide autorización: el artículo 21.1 dice que el derecho de reunión no la necesita.', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
