insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-014', (select id from leyes where slug = 'constitucion'), '22.4', 'Según la Constitución, las asociaciones solo pueden ser disueltas o suspendidas en sus actividades:', array['Por acuerdo del Consejo de Ministros', 'Por resolución del Ministerio del Interior', 'En virtud de resolución judicial motivada', 'Por resolución motivada del Registro de Asociaciones']::text[], 2, 'El artículo 22.4 lo reserva a los jueces: «Las asociaciones sólo podrán ser disueltas o suspendidas en sus actividades en virtud de resolución judicial motivada».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-015', (select id from leyes where slug = 'constitucion'), '53.2', 'Además de los derechos del artículo 14 y de la Sección 1.ª del Capítulo II, el recurso de amparo ante el Tribunal Constitucional protege:', array['El derecho a la propiedad privada', 'La objeción de conciencia reconocida en el artículo 30', 'El derecho al trabajo', 'El derecho a la protección de la salud']::text[], 1, 'El artículo 53.2, tras referirse a los derechos del artículo 14 y de la Sección primera del Capítulo segundo, añade: «Este último recurso será aplicable a la objeción de conciencia reconocida en el artículo 30».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 1 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-016', (select id from leyes where slug = 'constitucion'), '54', '¿Cómo define la Constitución al Defensor del Pueblo?', array['Como alto comisionado del Gobierno', 'Como órgano del Consejo General del Poder Judicial', 'Como alto comisionado del Congreso de los Diputados', 'Como alto comisionado de las Cortes Generales']::text[], 3, 'El artículo 54 lo define como «alto comisionado de las Cortes Generales, designado por éstas para la defensa de los derechos comprendidos en este Título». Lo designan las dos Cámaras, no solo el Congreso.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
