insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-017', (select id from leyes where slug = 'constitucion'), '56.3', 'Los actos del Rey que no estén refrendados, salvo lo dispuesto en el artículo 65.2:', array['Son anulables', 'Carecen de validez', 'Son válidos, pero no producen efectos', 'Deben ser convalidados por las Cortes Generales']::text[], 1, 'El artículo 56.3 establece que los actos del Rey «estarán siempre refrendados en la forma establecida en el artículo 64, careciendo de validez sin dicho refrendo, salvo lo dispuesto en el artículo 65, 2».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 2 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-018', (select id from leyes where slug = 'constitucion'), '64.1', '¿Quién refrenda la propuesta y el nombramiento del Presidente del Gobierno?', array['El Presidente del Gobierno saliente', 'El Presidente del Senado', 'El Presidente del Congreso', 'El Ministro de Justicia']::text[], 2, 'El artículo 64.1 dice: «La propuesta y el nombramiento del Presidente del Gobierno, y la disolución prevista en el artículo 99, serán refrendados por el Presidente del Congreso». El resto de actos del Rey los refrenda el Presidente del Gobierno o, en su caso, los ministros competentes.', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 2 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-019', (select id from leyes where slug = 'constitucion'), '68.1', 'Según el artículo 68.1 de la Constitución, el Congreso se compone de:', array['Un mínimo de 250 y un máximo de 350 Diputados', 'Un mínimo de 300 y un máximo de 400 Diputados', 'Un mínimo de 350 y un máximo de 400 Diputados', 'Un mínimo de 300 y un máximo de 350 Diputados']::text[], 1, 'El artículo 68.1 dice: «El Congreso se compone de un mínimo de 300 y un máximo de 400 Diputados, elegidos por sufragio universal, libre, igual, directo y secreto». La cifra concreta de 350 la fija la ley electoral, no la Constitución.', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ce-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 3 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-020', (select id from leyes where slug = 'constitucion'), '68.4', '¿Por cuánto tiempo es elegido el Congreso de los Diputados?', array['Tres años', 'Cinco años', 'Cuatro años', 'Seis años']::text[], 2, 'El artículo 68.4 dice: «El Congreso es elegido por cuatro años. El mandato de los Diputados termina cuatro años después de su elección o el día de la disolución de la Cámara».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
