insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-021', (select id from leyes where slug = 'constitucion'), '69.2', 'Con carácter general, ¿cuántos senadores se eligen en cada provincia?', array['Dos', 'Tres', 'Cinco', 'Cuatro']::text[], 3, 'El artículo 69.2 establece: «En cada provincia se elegirán cuatro Senadores por sufragio universal, libre, igual, directo y secreto». Las provincias insulares, Ceuta y Melilla tienen reglas propias (arts. 69.3 y 69.4).', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
