insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-022', (select id from leyes where slug = 'constitucion'), '81.2', '¿Qué mayoría exige la aprobación de una ley orgánica?', array['Mayoría de tres quintos de cada Cámara en una votación final', 'Mayoría absoluta del Congreso en una votación final sobre el conjunto del proyecto', 'Mayoría absoluta de cada Cámara en una votación final sobre el conjunto del proyecto', 'Mayoría simple del Congreso y mayoría absoluta del Senado en votación final']::text[], 1, 'El artículo 81.2 dice: «La aprobación, modificación o derogación de las leyes orgánicas exigirá mayoría absoluta del Congreso, en una votación final sobre el conjunto del proyecto».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
