insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-023', (select id from leyes where slug = 'constitucion'), '86.2', '¿En qué plazo debe someterse un decreto-ley a debate y votación de totalidad en el Congreso?', array['En los quince días siguientes a su promulgación', 'En los treinta días siguientes a su promulgación', 'En los cuarenta y cinco días siguientes a su publicación', 'En los sesenta días siguientes a su publicación']::text[], 1, 'Según el artículo 86.2, los decretos-leyes deben someterse a debate y votación de totalidad en el Congreso «en el plazo de los treinta días siguientes a su promulgación».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
