insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-024', (select id from leyes where slug = 'constitucion'), '99.3', 'Si el candidato a la Presidencia del Gobierno no obtiene la mayoría absoluta en la primera votación de investidura, la misma propuesta se somete a nueva votación:', array['Cuarenta y ocho horas después, y basta la mayoría simple', 'Veinticuatro horas después, y basta la mayoría simple', 'Cuarenta y ocho horas después, y se exige de nuevo la mayoría absoluta', 'Setenta y dos horas después, y basta la mayoría simple']::text[], 0, 'El artículo 99.3 dice que, si no alcanza la mayoría absoluta, «se someterá la misma propuesta a nueva votación cuarenta y ocho horas después de la anterior, y la confianza se entenderá otorgada si obtuviere la mayoría simple».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
