insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-025', (select id from leyes where slug = 'constitucion'), '99.5', 'Si ningún candidato obtiene la confianza del Congreso, el Rey disuelve ambas Cámaras cuando han pasado, desde la primera votación de investidura:', array['Un mes', 'Dos meses', 'Tres meses', 'Cuarenta y cinco días']::text[], 1, 'El artículo 99.5 establece: «Si transcurrido el plazo de dos meses, a partir de la primera votación de investidura, ningún candidato hubiere obtenido la confianza del Congreso, el Rey disolverá ambas Cámaras y convocará nuevas elecciones con el refrendo del Presidente del Congreso».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
