insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-026', (select id from leyes where slug = 'constitucion'), '113.3', 'Sobre la tramitación de la moción de censura, la Constitución establece que:', array['No puede votarse hasta pasados tres días desde su presentación, y en las primeras 24 horas pueden presentarse mociones alternativas', 'No puede votarse hasta pasados cinco días desde su presentación, y en los tres primeros días pueden presentarse mociones alternativas', 'No puede votarse hasta pasados siete días desde su presentación, y en los dos primeros días pueden presentarse mociones alternativas', 'No puede votarse hasta pasados cinco días desde su presentación, y en los dos primeros días pueden presentarse mociones alternativas']::text[], 3, 'El artículo 113.3 dice: «La moción de censura no podrá ser votada hasta que transcurran cinco días desde su presentación. En los dos primeros días de dicho plazo podrán presentarse mociones alternativas».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
