insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-027', (select id from leyes where slug = 'constitucion'), '122.3', 'Además de su Presidente, el Consejo General del Poder Judicial está integrado por:', array['Doce miembros nombrados por el Rey por un período de nueve años', 'Veinte miembros nombrados por el Rey por un período de cuatro años', 'Veinte miembros nombrados por el Rey por un período de cinco años', 'Veinte miembros nombrados por el Rey por un período de seis años']::text[], 2, 'El artículo 122.3 dice que el Consejo «estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
