insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-029', (select id from leyes where slug = 'constitucion'), '159.3', '¿Por cuánto tiempo se designa a los miembros del Tribunal Constitucional y cómo se renuevan?', array['Por doce años, y se renuevan por terceras partes cada cuatro', 'Por nueve años, y se renuevan por terceras partes cada tres', 'Por nueve años, y se renuevan por mitades cada cuatro años y medio', 'Por seis años, y se renuevan por mitades cada tres']::text[], 1, 'El artículo 159.3 dice: «Los miembros del Tribunal Constitucional serán designados por un período de nueve años y se renovarán por terceras partes cada tres».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
