insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-030', (select id from leyes where slug = 'constitucion'), '167.3', 'Una reforma constitucional aprobada por el procedimiento del artículo 167 se somete a referéndum cuando lo solicita:', array['Una quinta parte de los miembros de cualquiera de las Cámaras, dentro de los quince días siguientes a su aprobación', 'La mayoría absoluta del Senado, dentro de los quince días siguientes a su aprobación', 'Una décima parte de los miembros de cualquiera de las Cámaras, dentro de los quince días siguientes a su aprobación', 'Una décima parte de los miembros de ambas Cámaras, dentro de los treinta días siguientes a su aprobación']::text[], 2, 'El artículo 167.3 establece que la reforma «será sometida a referéndum para su ratificación cuando así lo soliciten, dentro de los quince días siguientes a su aprobación, una décima parte de los miembros de cualquiera de las Cámaras».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
