insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-001', (select id from leyes where slug = 'constitucion'), '56.1', 'Según el artículo 56.1 de la Constitución, el Rey es:', array['El Jefe del Gobierno y de las Fuerzas Armadas', 'El representante del pueblo español ante las Cortes', 'El Jefe del Estado, símbolo de su unidad y permanencia', 'El titular de la soberanía nacional']::text[], 2, 'El artículo 56.1 dice: «El Rey es el Jefe del Estado, símbolo de su unidad y permanencia».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
