insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-002', (select id from leyes where slug = 'constitucion'), '56.1', 'En las relaciones internacionales, el Rey:', array['Dirige la política exterior del Estado', 'Asume la más alta representación del Estado español', 'Representa al Gobierno de la Nación', 'Negocia y firma los tratados sin necesidad de refrendo']::text[], 1, 'El artículo 56.1 dice que el Rey «asume la más alta representación del Estado español en las relaciones internacionales». La política exterior la dirige el Gobierno (art. 97).', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
