insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-003', (select id from leyes where slug = 'constitucion'), '56.2', '¿Cuál es el título del Rey según la Constitución?', array['Rey de España', 'Rey de los españoles', 'Rey de España y de las Indias', 'Rey constitucional de España']::text[], 0, 'El artículo 56.2 dice: «Su título es el de Rey de España y podrá utilizar los demás que correspondan a la Corona».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
