insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-004', (select id from leyes where slug = 'constitucion'), '56.3', 'Según la Constitución, la persona del Rey:', array['Es inviolable, pero responde ante el Tribunal Supremo', 'Solo responde ante las Cortes Generales', 'Está sujeta a responsabilidad por los actos no refrendados', 'Es inviolable y no está sujeta a responsabilidad']::text[], 3, 'El artículo 56.3 dice: «La persona del Rey es inviolable y no está sujeta a responsabilidad».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
