insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-005', (select id from leyes where slug = 'constitucion'), '57.1', 'En la sucesión al trono, dentro del mismo grado, se prefiere:', array['A la persona de más edad, sin distinción de sexo', 'A la mujer sobre el varón y, en el mismo sexo, a la persona de menos edad', 'Al varón sobre la mujer y, en el mismo sexo, a la persona de más edad', 'A quien designen las Cortes Generales']::text[], 2, 'El artículo 57.1 establece que se prefiere, «en el mismo grado, el varón a la mujer, y en el mismo sexo, la persona de más edad a la de menos».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
