insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-006', (select id from leyes where slug = 'constitucion'), '57.2', 'El Príncipe heredero, desde su nacimiento o desde que se produzca el hecho que origine el llamamiento, tiene la dignidad de:', array['Príncipe de Gerona', 'Príncipe de Asturias', 'Príncipe de Viana', 'Infante de España']::text[], 1, 'El artículo 57.2 dice que el Príncipe heredero «tendrá la dignidad de Príncipe de Asturias» y los demás títulos vinculados tradicionalmente al sucesor.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
