insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-007', (select id from leyes where slug = 'constitucion'), '57.3', 'Extinguidas todas las líneas llamadas en Derecho, ¿quién provee a la sucesión en la Corona?', array['Las Cortes Generales', 'El Consejo de Ministros', 'El Tribunal Constitucional', 'El pueblo español mediante referéndum']::text[], 0, 'El artículo 57.3 dice que, extinguidas las líneas, «las Cortes Generales proveerán a la sucesión en la Corona en la forma que más convenga a los intereses de España».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
