insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-008', (select id from leyes where slug = 'constitucion'), '57.4', 'Las personas con derecho a la sucesión que contraigan matrimonio contra la expresa prohibición del Rey y de las Cortes Generales:', array['Quedan excluidas ellas, pero no sus descendientes', 'Pasan al último lugar del orden sucesorio', 'Mantienen sus derechos si el matrimonio lo aprueba el Gobierno', 'Quedan excluidas de la sucesión por sí y sus descendientes']::text[], 3, 'El artículo 57.4 dice que esas personas «quedarán excluidas en la sucesión a la Corona por sí y sus descendientes».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
