insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-009', (select id from leyes where slug = 'constitucion'), '57.5', 'Las abdicaciones y renuncias y las dudas de hecho o de derecho en el orden de sucesión a la Corona se resuelven:', array['Por real decreto del Consejo de Ministros', 'Por el Tribunal Constitucional', 'Por una ley orgánica', 'Por ley ordinaria aprobada en sesión conjunta']::text[], 2, 'El artículo 57.5 dice que «se resolverán por una ley orgánica».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
