insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-010', (select id from leyes where slug = 'constitucion'), '58', 'La Reina consorte o el consorte de la Reina:', array['Asumen las funciones del Rey en su ausencia', 'No pueden asumir funciones constitucionales, salvo lo dispuesto para la Regencia', 'Pueden asumir funciones constitucionales con autorización de las Cortes', 'Ejercen la tutela del Rey menor en todo caso']::text[], 1, 'El artículo 58 dice que los consortes «no podrán asumir funciones constitucionales, salvo lo dispuesto para la Regencia».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
