insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-011', (select id from leyes where slug = 'constitucion'), '59.1', 'Cuando el Rey es menor de edad, ejerce inmediatamente la Regencia:', array['El padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder', 'La persona que designen las Cortes Generales', 'El Presidente del Gobierno', 'El pariente de más edad de la Familia Real, aunque no sea el más próximo a suceder']::text[], 0, 'El artículo 59.1 dice que entrará a ejercer la Regencia «el padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
