insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-012', (select id from leyes where slug = 'constitucion'), '59.2', 'La inhabilitación del Rey para el ejercicio de su autoridad debe ser:', array['Declarada por el Tribunal Constitucional', 'Acordada por el Consejo de Ministros', 'Declarada por el Tribunal Supremo', 'Reconocida por las Cortes Generales']::text[], 3, 'El artículo 59.2 se refiere al Rey inhabilitado para el ejercicio de su autoridad cuando la imposibilidad fuere «reconocida por las Cortes Generales».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
