insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-013', (select id from leyes where slug = 'constitucion'), '59.3', 'Si no hay ninguna persona a quien corresponda la Regencia, las Cortes Generales la nombran y se compone de:', array['Una o dos personas', 'Tres personas', 'Una, tres o cinco personas', 'Cinco personas']::text[], 2, 'El artículo 59.3 dice que la Regencia nombrada por las Cortes «se compondrá de una, tres o cinco personas».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
