insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cor-015', (select id from leyes where slug = 'constitucion'), '60.1', '¿Quién es tutor del Rey menor en primer lugar?', array['La persona nombrada en el testamento del Rey difunto, si es mayor de edad y español de nacimiento', 'El Regente, en todo caso, mientras dure la minoría de edad del Rey', 'La persona que designe el Consejo de Ministros entre los parientes del Rey', 'El Presidente de las Cortes Generales, mientras no se nombre otro tutor']::text[], 0, 'El artículo 60.1 dice: «Será tutor del Rey menor la persona que en su testamento hubiese nombrado el Rey difunto, siempre que sea mayor de edad y español de nacimiento».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
