insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-016', (select id from leyes where slug = 'constitucion'), '74.1', 'Las Cámaras se reúnen en sesión conjunta para ejercer:', array['Las competencias legislativas sobre leyes orgánicas y leyes de bases', 'La aprobación de los Presupuestos Generales del Estado de cada ejercicio', 'Las competencias no legislativas que el Título II atribuye expresamente a las Cortes Generales', 'La investidura del Presidente del Gobierno y la moción de censura']::text[], 2, 'El artículo 74.1 dice: «Las Cámaras se reunirán en sesión conjunta para ejercer las competencias no legislativas que el Título II atribuye expresamente a las Cortes Generales».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
