insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-017', (select id from leyes where slug = 'constitucion'), '75.3', '¿Cuál de las siguientes materias puede delegarse en las Comisiones Legislativas Permanentes?', array['La reforma constitucional', 'Una ley ordinaria sobre una materia no excluida', 'Las leyes orgánicas y de bases', 'Los Presupuestos Generales del Estado']::text[], 1, 'El artículo 75.3 excluye de la delegación en comisiones «la reforma constitucional, las cuestiones internacionales, las leyes orgánicas y de bases y los Presupuestos Generales del Estado».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
