insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-022', (select id from leyes where slug = 'constitucion'), '90.2', 'Para que el Senado oponga su veto a un proyecto de ley, se requiere:', array['Mayoría absoluta', 'Mayoría simple', 'Mayoría de tres quintos', 'Mayoría de dos tercios']::text[], 0, 'El artículo 90.2 dice: «El veto deberá ser aprobado por mayoría absoluta».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
