insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-023', (select id from leyes where slug = 'constitucion'), '91', '¿En qué plazo sanciona el Rey las leyes aprobadas por las Cortes Generales?', array['Diez días', 'Treinta días', 'Un mes', 'Quince días']::text[], 3, 'El artículo 91 dice: «El Rey sancionará en el plazo de quince días las leyes aprobadas por las Cortes Generales».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
