insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-024', (select id from leyes where slug = 'constitucion'), '92.1', 'Las decisiones políticas de especial trascendencia pueden someterse a:', array['Referéndum vinculante de todos los ciudadanos', 'Consulta a las Comunidades Autónomas', 'Referéndum consultivo de todos los ciudadanos', 'Votación de las Cortes Generales en sesión conjunta']::text[], 2, 'El artículo 92.1 dice: «Las decisiones políticas de especial trascendencia podrán ser sometidas a referéndum consultivo de todos los ciudadanos».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
