insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-025', (select id from leyes where slug = 'constitucion'), '93', 'La celebración de tratados que atribuyen a una organización internacional el ejercicio de competencias derivadas de la Constitución se autoriza:', array['Mediante ley ordinaria', 'Mediante ley orgánica', 'Por acuerdo del Consejo de Ministros', 'Por mayoría de tres quintos de cada Cámara']::text[], 1, 'El artículo 93 dice: «Mediante ley orgánica se podrá autorizar la celebración de tratados por los que se atribuya a una organización o institución internacional el ejercicio de competencias derivadas de la Constitución».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
