insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('cg-026', (select id from leyes where slug = 'constitucion'), '86.1', 'Los decretos-leyes NO pueden afectar a:', array['El ordenamiento de las instituciones básicas del Estado', 'La regulación de los tributos en general', 'La organización de los Ministerios', 'La política económica del Gobierno']::text[], 0, 'El artículo 86.1 dice que los decretos-leyes «no podrán afectar al ordenamiento de las instituciones básicas del Estado», a los derechos del Título I, al régimen de las Comunidades Autónomas ni al Derecho electoral general.', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
