insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-031', (select id from leyes where slug = 'constitucion'), '69.3', 'Tras la reforma constitucional de 19 de mayo de 2026, ¿cuántos senadores elige la isla de Formentera?', array['Ninguno, porque comparte circunscripción con Ibiza', 'Uno', 'Dos', 'Tres']::text[], 1, 'La reforma de 2026 modificó el artículo 69.3, que ahora atribuye un senador «a cada una de las siguientes islas: Ibiza, Formentera, Menorca, Fuerteventura, La Gomera, El Hierro, Lanzarote y La Palma».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
