insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ce-032', (select id from leyes where slug = 'constitucion'), '69.3', 'Según el artículo 69.3 de la Constitución, ¿qué islas eligen tres senadores cada una?', array['Gran Canaria, Mallorca y Tenerife', 'Gran Canaria, Mallorca y Lanzarote', 'Mallorca, Menorca y Tenerife', 'Tenerife, Gran Canaria e Ibiza']::text[], 0, 'El artículo 69.3 dice que corresponden «tres a cada una de las islas mayores» (Gran Canaria, Mallorca y Tenerife) y uno a cada una de las demás islas con Cabildo o Consejo Insular.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
