insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-001', (select id from leyes where slug = 'constitucion'), '97', 'Según el artículo 97 de la Constitución, el Gobierno dirige:', array['La política exterior y la defensa, pero no la Administración militar', 'La política interior y la Administración civil, bajo la dirección del Rey', 'La política interior y exterior, la Administración civil y militar y la defensa del Estado', 'La política legislativa y presupuestaria del Estado']::text[], 2, 'El artículo 97 dice: «El Gobierno dirige la política interior y exterior, la Administración civil y militar y la defensa del Estado».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
