insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-002', (select id from leyes where slug = 'constitucion'), '98.1', 'Según la Constitución, el Gobierno se compone:', array['Del Presidente y de los Ministros, exclusivamente', 'Del Presidente, de los Vicepresidentes en su caso, de los Ministros y de los demás miembros que establezca la ley', 'Del Presidente, los Ministros y los Secretarios de Estado', 'Del Presidente, los Vicepresidentes, los Ministros y los Subsecretarios']::text[], 1, 'El artículo 98.1 dice: «El Gobierno se compone del Presidente, de los Vicepresidentes, en su caso, de los Ministros y de los demás miembros que establezca la ley».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
