insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-003', (select id from leyes where slug = 'constitucion'), '98.3', 'Los miembros del Gobierno:', array['No pueden ejercer otras funciones representativas que las propias del mandato parlamentario', 'No pueden ser Diputados ni Senadores', 'Pueden ejercer cualquier función representativa', 'Pueden ejercer funciones profesionales con autorización del Presidente']::text[], 0, 'El artículo 98.3 dice: «Los miembros del Gobierno no podrán ejercer otras funciones representativas que las propias del mandato parlamentario».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
