insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-004', (select id from leyes where slug = 'constitucion'), '99.1', 'Antes de proponer un candidato a la Presidencia del Gobierno, el Rey consulta:', array['Con el Consejo de Estado y con los Presidentes de ambas Cámaras', 'Con los Presidentes de las Comunidades Autónomas y de las Ciudades Autónomas', 'Con el Presidente del Senado y con el Presidente del Tribunal Constitucional', 'Con los representantes designados por los Grupos políticos con representación parlamentaria']::text[], 3, 'El artículo 99.1 dice que el Rey propone un candidato «previa consulta con los representantes designados por los Grupos políticos con representación parlamentaria».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
