insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-005', (select id from leyes where slug = 'constitucion'), '101.1', '¿Cuál de las siguientes NO es causa de cese del Gobierno según el artículo 101.1?', array['La celebración de elecciones generales', 'La pérdida de la confianza parlamentaria', 'La dimisión de un Vicepresidente', 'El fallecimiento de su Presidente']::text[], 2, 'El artículo 101.1 dice: «El Gobierno cesa tras la celebración de elecciones generales, en los casos de pérdida de la confianza parlamentaria previstos en la Constitución, o por dimisión o fallecimiento de su Presidente».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
