insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-006', (select id from leyes where slug = 'constitucion'), '102.1', 'La responsabilidad criminal del Presidente y los demás miembros del Gobierno es exigible ante:', array['El Tribunal Constitucional', 'La Sala de lo Penal del Tribunal Supremo', 'La Audiencia Nacional', 'El Congreso de los Diputados']::text[], 1, 'El artículo 102.1 dice que esa responsabilidad «será exigible, en su caso, ante la Sala de lo Penal del Tribunal Supremo».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
