insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-007', (select id from leyes where slug = 'constitucion'), '102.2', 'Si la acusación contra un miembro del Gobierno es por traición o delito contra la seguridad del Estado, solo puede plantearse:', array['A iniciativa de la cuarta parte de los miembros del Congreso y con la aprobación de su mayoría absoluta', 'A iniciativa de la décima parte del Congreso y con mayoría simple', 'A iniciativa del Fiscal General del Estado', 'A iniciativa de la tercera parte del Senado y con mayoría absoluta']::text[], 0, 'El artículo 102.2 dice que solo podrá ser planteada «por iniciativa de la cuarta parte de los miembros del Congreso, y con la aprobación de la mayoría absoluta del mismo».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
