insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-008', (select id from leyes where slug = 'constitucion'), '102.3', '¿Puede aplicarse la prerrogativa real de gracia a la responsabilidad criminal de los miembros del Gobierno?', array['Sí, con autorización de las Cortes', 'Sí, salvo en delitos de traición', 'Sí, si lo propone el Consejo de Ministros', 'No, en ningún supuesto del artículo 102']::text[], 3, 'El artículo 102.3 dice: «La prerrogativa real de gracia no será aplicable a ninguno de los supuestos del presente artículo».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
