insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-009', (select id from leyes where slug = 'constitucion'), '108', 'El Gobierno responde solidariamente en su gestión política ante:', array['Las Cortes Generales en sesión conjunta', 'El Senado', 'El Congreso de los Diputados', 'El Rey']::text[], 2, 'El artículo 108 dice: «El Gobierno responde solidariamente en su gestión política ante el Congreso de los Diputados».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
