insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-010', (select id from leyes where slug = 'constitucion'), '112', 'En la cuestión de confianza, la confianza se entiende otorgada cuando vota a favor:', array['La mayoría absoluta de los Diputados', 'La mayoría simple de los Diputados', 'Tres quintos de los Diputados', 'La mayoría absoluta de cada Cámara']::text[], 1, 'El artículo 112 dice: «La confianza se entenderá otorgada cuando vote a favor de la misma la mayoría simple de los Diputados».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
