insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-011', (select id from leyes where slug = 'constitucion'), '113.2', 'La moción de censura debe ser propuesta al menos por:', array['La décima parte de los Diputados, e incluir un candidato a la Presidencia', 'La quinta parte de los Diputados, sin necesidad de candidato', 'La décima parte de los Diputados, sin necesidad de candidato', 'Dos grupos parlamentarios, con un candidato']::text[], 0, 'El artículo 113.2 dice que la moción «deberá ser propuesta al menos por la décima parte de los Diputados, y habrá de incluir un candidato a la Presidencia del Gobierno».', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
