insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-012', (select id from leyes where slug = 'constitucion'), '113.4', 'Si la moción de censura no es aprobada, sus signatarios:', array['No pueden presentar otra durante un año', 'No pueden presentar otra en toda la legislatura', 'Pueden presentar otra pasados tres meses', 'No pueden presentar otra durante el mismo período de sesiones']::text[], 3, 'El artículo 113.4 dice: «Si la moción de censura no fuere aprobada por el Congreso, sus signatarios no podrán presentar otra durante el mismo período de sesiones».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
