insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-013', (select id from leyes where slug = 'constitucion'), '115.3', 'Tras una disolución de las Cámaras, ¿cuándo puede acordarse una nueva disolución por el procedimiento del artículo 115?', array['Cuando transcurran seis meses desde la anterior', 'Cuando transcurran dos años desde la anterior', 'Cuando transcurra un año desde la anterior', 'En cualquier momento']::text[], 2, 'El artículo 115.3 dice: «No procederá nueva disolución antes de que transcurra un año desde la anterior», salvo lo dispuesto en el artículo 99.5.', 2, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
