insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-014', (select id from leyes where slug = 'constitucion'), '116.2', 'El estado de alarma lo declara el Gobierno por un plazo máximo de:', array['Treinta días', 'Quince días', 'Diez días', 'Sesenta días']::text[], 1, 'El artículo 116.2 dice que el estado de alarma se declara «por un plazo máximo de quince días», dando cuenta al Congreso.', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
