insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-015', (select id from leyes where slug = 'constitucion'), '116.3', 'El estado de excepción no puede exceder de:', array['Treinta días, prorrogable por otro plazo igual', 'Quince días, prorrogable por otro plazo igual', 'Sesenta días, sin prórroga', 'Treinta días, sin prórroga']::text[], 0, 'El artículo 116.3 dice que su duración «no podrá exceder de treinta días, prorrogables por otro plazo igual».', 3, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
