insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-016', (select id from leyes where slug = 'ley-50-1997'), '1.2', 'Según la Ley 50/1997, del Gobierno, este se compone:', array['Del Presidente, los Ministros y los Secretarios de Estado', 'Del Presidente y de los Ministros, exclusivamente', 'Del Presidente, los Vicepresidentes, los Ministros y los Subsecretarios', 'Del Presidente, del Vicepresidente o Vicepresidentes en su caso, y de los Ministros']::text[], 3, 'El artículo 1.2 de la Ley 50/1997 dice: «El Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros».', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
