insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-017', (select id from leyes where slug = 'ley-50-1997'), '5.3', 'Según la Ley del Gobierno, las deliberaciones del Consejo de Ministros:', array['Son públicas', 'Se publican en el BOE', 'Son secretas', 'Son públicas salvo que el Presidente acuerde lo contrario']::text[], 2, 'El artículo 5.3 de la Ley 50/1997 dice: «Las deliberaciones del Consejo de Ministros serán secretas».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
