insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-018', (select id from leyes where slug = 'ley-50-1997'), '6.2', 'La creación, modificación y supresión de las Comisiones Delegadas del Gobierno se acuerda:', array['Por Real Decreto del Presidente del Gobierno, sin intervención del Consejo de Ministros', 'Por el Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno', 'Por ley de las Cortes Generales', 'Por orden del Ministro de la Presidencia']::text[], 1, 'El artículo 6.2 de la Ley 50/1997 dice que la creación, modificación y supresión de las Comisiones Delegadas «será acordada por el Consejo de Ministros mediante Real Decreto, a propuesta del Presidente del Gobierno».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
