insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-019', (select id from leyes where slug = 'ley-50-1997'), '11', 'Para ser miembro del Gobierno, la Ley 50/1997 exige:', array['Ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo y no estar inhabilitado', 'Ser español de origen, mayor de veinticinco años y tener la condición de diputado', 'Ser español, mayor de edad y funcionario de carrera de cualquier Administración', 'Ser mayor de edad, residir en España y tener reconocida experiencia profesional']::text[], 0, 'El artículo 11 de la Ley 50/1997 exige «ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo», así como no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme.', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
