insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-020', (select id from leyes where slug = 'ley-50-1997'), '13.1', 'En caso de vacante, ausencia o enfermedad, las funciones del Presidente del Gobierno las asumen:', array['El Ministro de la Presidencia, en todo caso y sin orden de prelación', 'El Presidente del Congreso de los Diputados, hasta que se nombre nuevo Presidente', 'El Ministro de mayor edad y, en su defecto, el de mayor antigüedad en el cargo', 'Los Vicepresidentes por su orden y, en su defecto, los Ministros según el orden de precedencia de los Departamentos']::text[], 3, 'El artículo 13.1 de la Ley 50/1997 dice que las funciones del Presidente «serán asumidas por los Vicepresidentes, de acuerdo con el correspondiente orden de prelación, y, en defecto de ellos, por los Ministros, según el orden de precedencia de los Departamentos».', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
