insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-021', (select id from leyes where slug = 'ley-50-1997'), '21.3', 'El Gobierno en funciones:', array['Puede ejercer todas sus competencias sin limitación', 'Solo puede adoptar medidas en estado de alarma', 'Limita su gestión al despacho ordinario de los asuntos públicos', 'Pierde todas sus competencias hasta la toma de posesión del nuevo Gobierno']::text[], 2, 'El artículo 21.3 de la Ley 50/1997 dice: que el Gobierno en funciones «limitará su gestión al despacho ordinario de los asuntos públicos», salvo casos de urgencia o interés general acreditados.', 1, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'gob-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 5 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-022', (select id from leyes where slug = 'ley-50-1997'), '21.4', '¿Cuál de las siguientes facultades NO puede ejercer el Presidente del Gobierno en funciones?', array['Despachar los asuntos ordinarios que correspondan a la Presidencia del Gobierno', 'Proponer al Rey la disolución de alguna de las Cámaras o de las Cortes Generales', 'Adoptar medidas urgentes debidamente acreditadas por razones de interés general', 'Asistir a reuniones internacionales en representación del Gobierno de España']::text[], 1, 'El artículo 21.4 de la Ley 50/1997 prohíbe al Presidente en funciones, entre otras cosas, «Proponer al Rey la disolución de alguna de las Cámaras, o de las Cortes Generales».', 3, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
