insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-023', (select id from leyes where slug = 'ley-50-1997'), '24.1', 'Las decisiones que aprueben normas reglamentarias de la competencia del Consejo de Ministros adoptan la forma de:', array['Reales Decretos acordados en Consejo de Ministros', 'Reales Decretos del Presidente del Gobierno', 'Órdenes ministeriales', 'Acuerdos del Consejo de Ministros']::text[], 0, 'El artículo 24.1 de la Ley 50/1997 dice que adoptarán la forma de «Reales Decretos acordados en Consejo de Ministros» las decisiones que aprueben normas reglamentarias de su competencia.', 2, '2025-04-03', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
