insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('gob-024', (select id from leyes where slug = 'constitucion'), '103.1', 'La Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de:', array['Eficacia, autonomía, descentralización y cooperación', 'Legalidad, jerarquía, centralización y coordinación', 'Eficiencia, jerarquía, solidaridad y colaboración', 'Eficacia, jerarquía, descentralización, desconcentración y coordinación']::text[], 3, 'El artículo 103.1 dice que la Administración actúa «de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación».', 1, '2026-05-20', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
