insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-001', (select id from leyes where slug = 'lo-3-2007'), '1.1', 'El objeto de la LO 3/2007 es:', array['Regular la violencia de género en el ámbito familiar y de la pareja', 'Hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres', 'Regular los permisos por nacimiento y cuidado de menor de las personas trabajadoras', 'Crear el Ministerio de Igualdad y fijar su estructura orgánica básica']::text[], 1, 'El artículo 1.1 dice que la ley tiene por objeto «hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-002', (select id from leyes where slug = 'lo-3-2007'), '3', 'Según la LO 3/2007, el principio de igualdad de trato entre mujeres y hombres supone:', array['La ausencia de toda discriminación, directa o indirecta, por razón de sexo', 'La prohibición de cualquier acción positiva', 'La paridad obligatoria en todos los órganos privados', 'La igualdad salarial, exclusivamente']::text[], 0, 'El artículo 3 dice que este principio «supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-003', (select id from leyes where slug = 'lo-3-2007'), '6.1', 'La LO 3/2007 define la discriminación directa por razón de sexo como la situación de una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo:', array['De forma neutra pero con efectos desfavorables', 'Mediante una disposición aparentemente neutra', 'De manera diferente, aunque esté justificado objetivamente', 'De manera menos favorable que otra en situación comparable']::text[], 3, 'El artículo 6.1 la define como la situación de quien sea tratada, en atención a su sexo, «de manera menos favorable que otra en situación comparable».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-004', (select id from leyes where slug = 'lo-3-2007'), '7.1', 'Según la LO 3/2007, constituye acoso sexual:', array['Cualquier comportamiento realizado en función del sexo de una persona', 'Cualquier trato desfavorable relacionado con el embarazo', 'Cualquier comportamiento, verbal o físico, de naturaleza sexual que atente contra la dignidad de una persona', 'Cualquier disposición aparentemente neutra que perjudique a un sexo']::text[], 2, 'El artículo 7.1 define el acoso sexual como «cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
