insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-005', (select id from leyes where slug = 'lo-3-2007'), '8', 'Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad constituye:', array['Discriminación indirecta por razón de sexo', 'Discriminación directa por razón de sexo', 'Acoso por razón de sexo', 'Una acción positiva']::text[], 1, 'El artículo 8 dice: «Constituye discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-006', (select id from leyes where slug = 'lo-3-2007'), '11.1', 'Según la LO 3/2007, las acciones positivas son:', array['Medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho', 'Medidas permanentes que favorecen a los hombres en sectores masculinizados', 'Sanciones a las empresas que discriminan por razón de sexo en la contratación', 'Subvenciones generales a las familias con hijos menores a su cargo']::text[], 0, 'El artículo 11.1 habla de adoptar «medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-007', (select id from leyes where slug = 'lo-3-2007'), '13.1', 'En los procedimientos en que se aleguen actuaciones discriminatorias por razón de sexo, la carga de la prueba:', array['Corresponde siempre a quien alega la discriminación', 'Corresponde al Ministerio Fiscal', 'Se reparte por igual entre las partes', 'Corresponde a la parte demandada, que debe probar la ausencia de discriminación']::text[], 3, 'El artículo 13.1 dice que, aportados indicios, «corresponderá a la persona demandada probar la ausencia de discriminación».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
