insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-008', (select id from leyes where slug = 'lo-3-2007'), '15', 'El principio de igualdad de trato y oportunidades entre mujeres y hombres informa la actuación de todos los Poderes Públicos:', array['Con carácter subsidiario', 'Solo en materia laboral', 'Con carácter transversal', 'Solo en la Administración General del Estado']::text[], 2, 'El artículo 15 dice que este principio «informará, con carácter transversal, la actuación de todos los Poderes Públicos».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
