insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-009', (select id from leyes where slug = 'lo-3-2007'), '19', 'Los proyectos de disposiciones de carácter general que se sometan al Consejo de Ministros deben incorporar:', array['Un dictamen del Instituto de las Mujeres', 'Un informe sobre su impacto por razón de género', 'Una autorización del Ministerio de Igualdad', 'Un plan de igualdad']::text[], 1, 'El artículo 19 dice que deberán incorporar «un informe sobre su impacto por razón de género».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
