insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-010', (select id from leyes where slug = 'lo-3-2007'), '45.2', 'Según la LO 3/2007, las empresas están obligadas a elaborar y aplicar un plan de igualdad cuando tienen:', array['Cincuenta o más trabajadores', 'Doscientos cincuenta o más trabajadores', 'Cien o más trabajadores', 'Veinticinco o más trabajadores']::text[], 0, 'El artículo 45.2 obliga a las empresas «de cincuenta o más trabajadores».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
