insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-011', (select id from leyes where slug = 'lo-3-2007'), '46.1', 'Según la LO 3/2007, los planes de igualdad de las empresas son:', array['Un código ético de adhesión voluntaria aprobado por la dirección de la empresa', 'Un acuerdo individual firmado con cada trabajadora de la plantilla', 'Un informe anual de retribuciones remitido a la Inspección de Trabajo', 'Un conjunto ordenado de medidas, adoptadas después de un diagnóstico de situación']::text[], 3, 'El artículo 46.1 define los planes de igualdad como «un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
