insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-012', (select id from leyes where slug = 'lo-3-2007'), '64', '¿Cuándo aprueba el Gobierno el Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado?', array['Cada año, con los Presupuestos', 'Cada cinco años', 'Al inicio de cada legislatura', 'Cuando lo solicite el Instituto de las Mujeres']::text[], 2, 'El artículo 64 dice: «El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
