insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-013', (select id from leyes where slug = 'lo-3-2007'), '77', 'Según la LO 3/2007, en todos los Ministerios el desarrollo de las funciones relacionadas con el principio de igualdad se encomienda:', array['A una comisión parlamentaria', 'A uno de sus órganos directivos', 'A la Subsecretaría de Igualdad de cada Ministerio, de nueva creación', 'Al Instituto de las Mujeres']::text[], 1, 'El artículo 77 dice: «En todos los Ministerios se encomendará a uno de sus órganos directivos el desarrollo de las funciones relacionadas con el principio de igualdad entre mujeres y hombres».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-014', (select id from leyes where slug = 'lo-1-2004'), '1.1', 'La LO 1/2004 tiene por objeto actuar contra la violencia ejercida sobre las mujeres por parte de:', array['Quienes sean o hayan sido sus cónyuges o estén o hayan estado ligados a ellas por relaciones similares de afectividad', 'Cualquier persona, aunque no tenga ni haya tenido relación con la víctima', 'Solo sus cónyuges actuales, siempre que exista convivencia en el mismo domicilio', 'Sus familiares de primer grado, tanto por consanguinidad como por afinidad']::text[], 0, 'El artículo 1.1 se refiere a la violencia ejercida sobre las mujeres «por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia».', 2, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-015', (select id from leyes where slug = 'lo-1-2004'), '1.3', 'La violencia de género a que se refiere la LO 1/2004 comprende:', array['Solo la violencia física que cause lesiones que requieran asistencia médica o quirúrgica', 'Solo la violencia física y sexual, pero no la psicológica, las amenazas ni las coacciones', 'Solo los actos de violencia cometidos en el domicilio familiar y en presencia de menores', 'Todo acto de violencia física y psicológica, incluidas agresiones sexuales, amenazas y coacciones']::text[], 3, 'El artículo 1.3 dice que «comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad».', 2, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-016', (select id from leyes where slug = 'lo-1-2004'), '24', 'La funcionaria víctima de violencia de género tiene derecho, entre otros, a:', array['Una indemnización automática a cargo de la Administración en la que presta servicios', 'La jubilación anticipada sin reducción de la pensión que le corresponda', 'La reducción o reordenación de su tiempo de trabajo, la movilidad geográfica y la excedencia', 'Un ascenso de grado personal y un complemento retributivo específico']::text[], 2, 'El artículo 24 dice: «La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia en los términos que se determinen en su legislación específica».', 2, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-017', (select id from leyes where slug = 'lo-1-2004'), '18.1', 'Según la LO 1/2004, las mujeres víctimas de violencia de género tienen derecho a:', array['Recibir información solo si presentan denuncia', 'Recibir plena información y asesoramiento adecuado a su situación personal', 'Recibir información a través de su abogado, exclusivamente', 'Recibir información solo en el juzgado']::text[], 1, 'El artículo 18.1 dice: «Las mujeres víctimas de violencia de género tienen derecho a recibir plena información y asesoramiento adecuado a su situación personal».', 1, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-018', (select id from leyes where slug = 'lo-1-2004'), '19.1', 'Las mujeres víctimas de violencia de género tienen derecho a servicios sociales:', array['De atención, de emergencia, de apoyo y acogida y de recuperación integral', 'Solo de emergencia, durante las primeras setenta y dos horas', 'Solo de acogida temporal, mientras dure el procedimiento judicial', 'De atención, siempre que tengan hijos menores a su cargo']::text[], 0, 'El artículo 19.1 reconoce el derecho «a servicios sociales de atención, de emergencia, de apoyo y acogida y de recuperación integral».', 2, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-019', (select id from leyes where slug = 'lo-1-2004'), '30.1', '¿Qué órgano colegiado crea la LO 1/2004, adscrito al Ministerio competente, para asesorar y analizar la violencia de género?', array['El Consejo Estatal de la Mujer', 'La Comisión Nacional de Igualdad', 'El Instituto de la Mujer y para la Igualdad de Oportunidades', 'El Observatorio Estatal de Violencia sobre la Mujer']::text[], 3, 'El artículo 30 de la LO 1/2004 crea el «Observatorio Estatal de Violencia sobre la Mujer», órgano colegiado de asesoramiento y análisis.', 2, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-020', (select id from leyes where slug = 'lo-1-2004'), '27.1', 'La ayuda económica del artículo 27 de la LO 1/2004 se dirige a las víctimas que:', array['Hayan presentado denuncia, sin que se exija ningún otro requisito', 'Sean menores de edad o tengan reconocida una discapacidad', 'Carezcan de rentas suficientes y tengan especiales dificultades para obtener un empleo', 'Trabajen en la Administración y hayan solicitado la excedencia']::text[], 2, 'El artículo 27.1 la vincula a que, por su edad, falta de preparación y circunstancias sociales, la víctima «tendrá especiales dificultades para obtener un empleo».', 3, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-021', (select id from leyes where slug = 'lo-1-2004'), '23', 'Las situaciones de violencia de género que dan lugar al reconocimiento de los derechos laborales y de Seguridad Social se acreditan, entre otros medios, mediante:', array['Declaración jurada de la víctima presentada ante su empleador o la Administración', 'Sentencia condenatoria, orden de protección u otra resolución judicial que acuerde una medida cautelar a favor de la víctima', 'Certificado de empadronamiento que acredite el cambio de domicilio de la víctima', 'Informe del centro de salud, como único medio de prueba admitido']::text[], 1, 'El artículo 23 dice que se acreditarán «una orden de protección o cualquier otra resolución judicial que acuerde una medida cautelar a favor de la víctima», además de por sentencia condenatoria y otros medios.', 3, '2022-10-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'ig-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 16 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('ig-022', (select id from leyes where slug = 'lo-3-2007'), 'DA 1ª', 'A efectos de la LO 3/2007, la composición equilibrada supone que las personas de cada sexo no superen ni sean menos de:', array['El sesenta por ciento ni el cuarenta por ciento', 'El setenta por ciento ni el treinta por ciento', 'El cincuenta y cinco por ciento ni el cuarenta y cinco por ciento', 'El sesenta y cinco por ciento ni el treinta y cinco por ciento']::text[], 0, 'La disposición adicional primera dice que en el conjunto «las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
