insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-001', (select id from leyes where slug = 'ley-39-2015'), '21.3', 'Cuando la norma reguladora de un procedimiento no fija el plazo máximo para resolver, ¿cuál es ese plazo?', array['Un mes', 'Tres meses', 'Seis meses', 'Dos meses']::text[], 1, 'El artículo 21.3 lo resuelve: «Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-002', (select id from leyes where slug = 'ley-39-2015'), '21.2', 'El plazo máximo para notificar la resolución expresa que fije la norma reguladora del procedimiento:', array['No puede exceder de tres meses, salvo que una norma con rango de ley establezca uno mayor', 'No puede exceder de seis meses, en ningún caso', 'No puede exceder de seis meses, salvo que una norma con rango de ley establezca uno mayor o así lo prevea el Derecho de la Unión Europea', 'No puede exceder de un año, salvo que lo prevea el Derecho de la Unión Europea']::text[], 2, 'El artículo 21.2 dice que este plazo «no podrá exceder de seis meses salvo que una norma con rango de ley establezca uno mayor o así venga previsto en el Derecho de la Unión Europea».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-003', (select id from leyes where slug = 'ley-39-2015'), '30.2', 'Cuando los plazos se señalan por días y no se dice otra cosa, ¿qué días se excluyen del cómputo?', array['Los sábados, los domingos y los declarados festivos', 'Solo los domingos y los declarados festivos', 'Los sábados y los domingos, pero no los festivos locales', 'Solo los declarados festivos']::text[], 0, 'El artículo 30.2 establece que, cuando los plazos se señalen por días, «se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-004', (select id from leyes where slug = 'ley-39-2015'), '30.4', 'Si un plazo se fija en meses, ¿desde cuándo se computa?', array['Desde el mismo día de la notificación o publicación del acto', 'Desde el día en que se dictó el acto', 'Desde el tercer día hábil siguiente a la notificación', 'Desde el día siguiente a aquel en que tenga lugar la notificación o publicación del acto']::text[], 3, 'El artículo 30.4 dice que los plazos en meses o años «se computarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-005', (select id from leyes where slug = 'ley-39-2015'), '30.5', '¿Qué ocurre cuando el último día de un plazo es inhábil?', array['El plazo vence el día hábil anterior', 'El plazo vence ese mismo día', 'Se entiende prorrogado al primer día hábil siguiente', 'Se prorroga dos días hábiles']::text[], 2, 'El artículo 30.5 lo dice así: «Cuando el último día del plazo sea inhábil, se entenderá prorrogado al primer día hábil siguiente».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
