insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-006', (select id from leyes where slug = 'ley-39-2015'), '32.1', 'La Administración puede acordar una ampliación de los plazos establecidos que no exceda de:', array['La mitad de los mismos', 'El doble de los mismos', 'Un tercio de los mismos', 'Diez días']::text[], 0, 'El artículo 32.1 permite conceder «una ampliación de los plazos establecidos, que no exceda de la mitad de los mismos, si las circunstancias lo aconsejan y con ello no se perjudican derechos de tercero».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-007', (select id from leyes where slug = 'ley-39-2015'), '32.3', 'Contra el acuerdo que resuelve sobre la ampliación de plazos:', array['Cabe recurso de alzada ante el órgano superior jerárquico del que lo dictó', 'Cabe recurso potestativo de reposición ante el mismo órgano que lo dictó', 'No cabe recurso, sin perjuicio del que proceda contra la resolución que ponga fin al procedimiento', 'Cabe recurso extraordinario de revisión en los supuestos tasados por la ley']::text[], 2, 'El artículo 32.3 dice: «Los acuerdos sobre ampliación de plazos o sobre su denegación no serán susceptibles de recurso, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-007', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-008', (select id from leyes where slug = 'ley-39-2015'), '14.2', '¿Quién de los siguientes NO está obligado, con carácter general, a relacionarse electrónicamente con las Administraciones Públicas?', array['Las personas jurídicas', 'Las entidades sin personalidad jurídica', 'Quienes ejerzan una actividad profesional con colegiación obligatoria, en los trámites de esa actividad', 'Las personas físicas']::text[], 3, 'Las personas físicas pueden elegir si se comunican por medios electrónicos o no (art. 14.1). El artículo 14.2 obliga, entre otros, a «las personas jurídicas», «las entidades sin personalidad jurídica» y a quienes ejerzan «una actividad profesional para la que se requiera colegiación obligatoria».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-009', (select id from leyes where slug = 'ley-39-2015'), '40.2', '¿En qué plazo debe cursarse la notificación de un acto?', array['Cinco días desde la fecha en que se dictó el acto', 'Diez días desde la fecha en que se dictó el acto', 'Quince días desde la fecha en que se dictó el acto', 'Un mes desde la fecha en que se dictó el acto']::text[], 1, 'El artículo 40.2 establece: «Toda notificación deberá ser cursada dentro del plazo de diez días a partir de la fecha en que el acto haya sido dictado».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-010', (select id from leyes where slug = 'ley-39-2015'), '43.2', 'Una notificación electrónica obligatoria se entiende rechazada si no se accede a su contenido en un plazo, desde su puesta a disposición, de:', array['Diez días hábiles', 'Quince días naturales', 'Cinco días hábiles', 'Diez días naturales']::text[], 3, 'El artículo 43.2 dice que se entenderá rechazada «cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido». Es uno de los pocos plazos de la ley en días naturales.', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-011', (select id from leyes where slug = 'ley-39-2015'), '48.1', '¿Cuál de los siguientes actos NO es nulo de pleno derecho, sino anulable?', array['El dictado por un órgano manifiestamente incompetente por razón de la materia o del territorio', 'El que incurre en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder', 'El que tiene un contenido imposible', 'El dictado prescindiendo total y absolutamente del procedimiento legalmente establecido']::text[], 1, 'La infracción del ordenamiento jurídico es la causa general de anulabilidad del artículo 48.1: «Son anulables los actos de la Administración que incurran en cualquier infracción del ordenamiento jurídico, incluso la desviación de poder». Las otras tres opciones son causas de nulidad del artículo 47.1.', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-012', (select id from leyes where slug = 'ley-39-2015'), '48.3', 'Realizar una actuación administrativa fuera del tiempo establecido para ella:', array['Determina siempre la nulidad de pleno derecho del acto', 'Determina siempre la anulabilidad del acto', 'Solo implica la anulabilidad cuando así lo imponga la naturaleza del término o plazo', 'No afecta nunca a la validez del acto']::text[], 2, 'El artículo 48.3 establece: «La realización de actuaciones administrativas fuera del tiempo establecido para ellas sólo implicará la anulabilidad del acto cuando así lo imponga la naturaleza del término o plazo».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-013', (select id from leyes where slug = 'ley-39-2015'), '39.1', 'Como regla general, ¿desde cuándo producen efectos los actos administrativos?', array['Desde su notificación a todos los interesados en el procedimiento', 'Desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa', 'Desde su publicación en el boletín oficial que corresponda', 'Desde que son firmes en vía administrativa']::text[], 1, 'El artículo 39.1 dice que los actos «se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa». El artículo 39.2 prevé que la eficacia se demore en algunos casos, por ejemplo cuando dependa de la notificación.', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-014', (select id from leyes where slug = 'ley-39-2015'), '68.1', 'Si una solicitud no reúne los requisitos exigidos, se requiere al interesado para que la subsane en un plazo de:', array['Cinco días', 'Quince días', 'Diez días', 'Veinte días']::text[], 2, 'El artículo 68.1 dice que se requerirá al interesado «para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-014', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-015', (select id from leyes where slug = 'ley-39-2015'), '82.2', 'En el trámite de audiencia, los interesados pueden alegar y presentar documentos en un plazo:', array['No inferior a diez días ni superior a quince', 'No inferior a cinco días ni superior a diez', 'No inferior a quince días ni superior a veinte', 'De diez días exactos']::text[], 0, 'El artículo 82.2 establece: «Los interesados, en un plazo no inferior a diez días ni superior a quince, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-015', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-016', (select id from leyes where slug = 'ley-39-2015'), '83.2', 'En el trámite de información pública, el plazo para formular alegaciones no puede ser inferior a:', array['Diez días', 'Quince días', 'Veinte días', 'Treinta días']::text[], 2, 'El artículo 83.2 dice que el anuncio determinará «el plazo para formular alegaciones, que en ningún caso podrá ser inferior a veinte días».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-017', (select id from leyes where slug = 'ley-39-2015'), '24.1', 'En un procedimiento iniciado a solicitud del interesado, si vence el plazo máximo sin resolución expresa, como regla general la solicitud:', array['Se entiende desestimada', 'Se entiende estimada por silencio administrativo, salvo las excepciones previstas', 'Se archiva por caducidad', 'Queda pendiente hasta que se dicte resolución, sin efecto alguno']::text[], 1, 'El artículo 24.1 establece que el vencimiento del plazo sin resolución «legitima al interesado o interesados para entenderla estimada por silencio administrativo», salvo que una norma con rango de ley, del Derecho de la Unión Europea o del Derecho internacional aplicable en España diga lo contrario.', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-018', (select id from leyes where slug = 'ley-39-2015'), '24.1', 'En los procedimientos de impugnación de actos, el silencio es desestimatorio. ¿En qué caso se entiende estimado el recurso?', array['Cuando se trata de un recurso potestativo de reposición interpuesto contra un acto expreso', 'Cuando lo interpone una persona jurídica obligada a relacionarse electrónicamente', 'Cuando el acto impugnado es de gravamen o desfavorable para el interesado', 'Cuando el recurso de alzada se interpone contra la desestimación por silencio de una solicitud y no se resuelve en plazo']::text[], 3, 'El artículo 24.1 dice que, aunque en la impugnación de actos el silencio es desestimatorio, «cuando el recurso de alzada se haya interpuesto contra la desestimación por silencio administrativo de una solicitud por el transcurso del plazo, se entenderá estimado el mismo si, llegado el plazo de resolución, el órgano administrativo competente no dictase y notificase resolución expresa».', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-018', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-019', (select id from leyes where slug = 'ley-39-2015'), '25.1.b', 'En un procedimiento sancionador iniciado de oficio, si vence el plazo máximo sin resolución expresa, se produce:', array['El silencio estimatorio', 'El silencio desestimatorio', 'La caducidad', 'La prescripción de la infracción']::text[], 2, 'El artículo 25.1.b establece que en los procedimientos en que la Administración ejerza «potestades sancionadoras o, en general, de intervención, susceptibles de producir efectos desfavorables o de gravamen, se producirá la caducidad».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-020', (select id from leyes where slug = 'ley-39-2015'), '122.1', '¿Cuál es el plazo para interponer un recurso de alzada contra un acto expreso?', array['Un mes', 'Dos meses', 'Quince días', 'Tres meses']::text[], 0, 'El artículo 122.1 dice: «El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
