insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-021', (select id from leyes where slug = 'ley-39-2015'), '122.2', '¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso de alzada?', array['Un mes', 'Tres meses', 'Seis meses', 'Dos meses']::text[], 1, 'El artículo 122.2 establece: «El plazo máximo para dictar y notificar la resolución será de tres meses». Si pasa sin resolución, el recurso se entiende desestimado, salvo el caso del artículo 24.1.', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
