insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-022', (select id from leyes where slug = 'ley-39-2015'), '124.2', '¿Cuál es el plazo máximo para dictar y notificar la resolución del recurso potestativo de reposición?', array['Quince días', 'Tres meses', 'Un mes', 'Dos meses']::text[], 2, 'El artículo 124.2 lo fija: «El plazo máximo para dictar y notificar la resolución del recurso será de un mes».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-022', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-023', (select id from leyes where slug = 'ley-39-2015'), '125.2', 'Cuando el recurso extraordinario de revisión se basa en un error de hecho que resulta de los documentos del expediente, el plazo para interponerlo es de:', array['Tres meses desde la notificación de la resolución impugnada', 'Cuatro años desde la notificación de la resolución impugnada', 'Un año desde la notificación de la resolución impugnada', 'Dos años desde que la resolución quedó firme']::text[], 1, 'El artículo 125.2 dice que, en la causa a) del apartado 1, el recurso se interpone «dentro del plazo de cuatro años siguientes a la fecha de la notificación de la resolución impugnada». En los demás casos el plazo es de tres meses.', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l39-023', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-024', (select id from leyes where slug = 'ley-39-2015'), '109.2', 'Las Administraciones pueden rectificar los errores materiales, de hecho o aritméticos de sus actos:', array['En el plazo de un mes desde la notificación', 'Solo a instancia del interesado, en el plazo de cuatro años', 'Solo mediante el procedimiento de revisión de oficio', 'En cualquier momento, de oficio o a instancia de los interesados']::text[], 3, 'El artículo 109.2 establece que las Administraciones pueden «rectificar en cualquier momento, de oficio o a instancia de los interesados, los errores materiales, de hecho o aritméticos existentes en sus actos».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
