insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-025', (select id from leyes where slug = 'ley-39-2015'), '107.2', 'La declaración de lesividad de un acto anulable no puede adoptarse cuando han pasado:', array['Cuatro años desde la notificación del acto', 'Un año desde la notificación del acto', 'Cuatro años desde que se dictó el acto', 'Seis meses desde que se dictó el acto']::text[], 2, 'El artículo 107.2 dice: «La declaración de lesividad no podrá adoptarse una vez transcurridos cuatro años desde que se dictó el acto administrativo». El plazo cuenta desde que se dicta, no desde la notificación.', 3, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
