insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-026', (select id from leyes where slug = 'ley-39-2015'), '95.1', 'Si un procedimiento iniciado a solicitud del interesado se paraliza por su culpa, la Administración le advierte de que se producirá la caducidad cuando pasen:', array['Un mes', 'Tres meses', 'Seis meses', 'Dos meses']::text[], 1, 'El artículo 95.1 dice que la Administración «le advertirá que, transcurridos tres meses, se producirá la caducidad del procedimiento».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
