insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-027', (select id from leyes where slug = 'ley-39-2015'), '58', '¿Cuál de las siguientes NO es una forma de iniciar un procedimiento de oficio?', array['Por orden superior', 'Por petición razonada de otros órganos', 'Por denuncia', 'Por solicitud del interesado']::text[], 3, 'La solicitud del interesado es la otra vía de inicio, distinta de la de oficio (art. 54). El artículo 58 dice: «Los procedimientos se iniciarán de oficio por acuerdo del órgano competente, bien por propia iniciativa o como consecuencia de orden superior, a petición razonada de otros órganos o por denuncia».', 1, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
