insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l39-028', (select id from leyes where slug = 'ley-39-2015'), '96.6', 'Salvo que les quede menos en la tramitación ordinaria, los procedimientos tramitados de forma simplificada deben resolverse en:', array['Treinta días', 'Quince días', 'Diez días', 'Cuarenta y cinco días']::text[], 0, 'El artículo 96.6 establece que estos procedimientos «deberán ser resueltos en treinta días, a contar desde el siguiente al que se notifique al interesado el acuerdo de tramitación simplificada del procedimiento».', 2, '2024-11-07', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
