insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-021', (select id from leyes where slug = 'ley-40-2015'), '23.2.b', 'Es motivo de abstención el parentesco con cualquiera de los interesados:', array['De consanguinidad dentro del segundo grado o de afinidad dentro del primero', 'De consanguinidad o afinidad dentro del cuarto grado', 'De consanguinidad dentro del tercer grado o de afinidad dentro del segundo', 'De consanguinidad dentro del cuarto grado o de afinidad dentro del segundo']::text[], 3, 'El artículo 23.2.b) se refiere al «parentesco de consanguinidad dentro del cuarto grado o de afinidad dentro del segundo».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-021', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-022', (select id from leyes where slug = 'ley-40-2015'), '23.2.e', 'Es motivo de abstención haber prestado servicios profesionales a una persona interesada directamente en el asunto:', array['En el último año', 'En los cuatro últimos años', 'En los dos últimos años', 'En los cinco últimos años']::text[], 2, 'El artículo 23.2.e) incluye tener relación de servicio con persona interesada directamente en el asunto, «o haberle prestado en los dos últimos años servicios profesionales de cualquier tipo».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
