insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-023', (select id from leyes where slug = 'ley-40-2015'), '24.4', 'Si el recusado niega la causa de recusación, el superior resuelve en el plazo de:', array['Diez días', 'Tres días', 'Cinco días', 'Un día']::text[], 1, 'El artículo 24.4 dice: «Si el recusado niega la causa de recusación, el superior resolverá en el plazo de tres días».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
