insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-024', (select id from leyes where slug = 'ley-40-2015'), '24.3', 'Planteada la recusación, ¿cuándo debe el recusado manifestar a su superior si se da o no en él la causa alegada?', array['Al día siguiente', 'En el plazo de tres días', 'En el plazo de cinco días', 'En el plazo de diez días']::text[], 0, 'El artículo 24.3 establece: «En el día siguiente el recusado manifestará a su inmediato superior si se da o no en él la causa alegada».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-024', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-025', (select id from leyes where slug = 'ley-40-2015'), '24.1', 'La recusación pueden promoverla los interesados:', array['Solo en los diez días siguientes al inicio del procedimiento', 'Solo antes del trámite de audiencia', 'Solo al interponer recurso contra la resolución', 'En cualquier momento de la tramitación del procedimiento']::text[], 3, 'El artículo 24.1 dice que podrá promoverse recusación por los interesados «en cualquier momento de la tramitación del procedimiento».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
