insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-026', (select id from leyes where slug = 'ley-40-2015'), '29.1', 'Según la Ley 40/2015, las sanciones administrativas:', array['Pueden implicar privación de libertad subsidiaria si no se paga la multa', 'Pueden implicar privación de libertad solo si lo prevé una ley orgánica', 'En ningún caso pueden implicar, directa o subsidiariamente, privación de libertad', 'Solo pueden ser de naturaleza pecuniaria']::text[], 2, 'El artículo 29.1 dice que las sanciones, sean o no pecuniarias, «en ningún caso podrán implicar, directa o subsidiariamente, privación de libertad».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-026', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-027', (select id from leyes where slug = 'ley-40-2015'), '29.3.d', 'A efectos de graduar la sanción, la reincidencia se produce por la comisión de más de una infracción de la misma naturaleza, declarada por resolución firme en vía administrativa, en el término de:', array['Seis meses', 'Un año', 'Dos años', 'Tres años']::text[], 1, 'El artículo 29.3.d) define la reincidencia «por comisión en el término de un año de más de una infracción de la misma naturaleza» declarada por resolución firme en vía administrativa.', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-027', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-028', (select id from leyes where slug = 'ley-40-2015'), '30.1', 'Si la ley que establece las infracciones no fija plazos de prescripción, las infracciones leves prescriben:', array['A los seis meses', 'Al año', 'A los tres meses', 'A los dos años']::text[], 0, 'El artículo 30.1 dispone que, a falta de plazo en la ley, «las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
