insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-029', (select id from leyes where slug = 'ley-40-2015'), '30.1', 'Si la ley no fija plazos de prescripción, las sanciones impuestas por faltas leves prescriben:', array['A los seis meses', 'A los dos años', 'A los tres meses', 'Al año']::text[], 3, 'El artículo 30.1 establece que, a falta de plazo en la ley, prescriben «las impuestas por faltas leves al año».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
