insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-030', (select id from leyes where slug = 'ley-40-2015'), '28.1', 'Según el artículo 28.1 de la Ley 40/2015, solo pueden ser sancionados por infracciones administrativas los responsables de los hechos:', array['A título de dolo, exclusivamente', 'Con independencia de su culpabilidad', 'A título de dolo o culpa', 'A título de culpa grave']::text[], 2, 'El artículo 28.1 dice que solo pueden ser sancionados quienes «resulten responsables de los mismos a título de dolo o culpa».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
