insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-031', (select id from leyes where slug = 'ley-40-2015'), '32.2', 'En la responsabilidad patrimonial de las Administraciones, el daño alegado debe ser:', array['Efectivo, previsible e individualizado', 'Efectivo, evaluable económicamente e individualizado', 'Evaluable económicamente, colectivo y actual', 'Efectivo, futuro y evaluable económicamente']::text[], 1, 'El artículo 32.2 dice: «el daño alegado habrá de ser efectivo, evaluable económicamente e individualizado con relación a una persona o grupo de personas».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-032', (select id from leyes where slug = 'ley-40-2015'), '32.1', 'Los particulares tienen derecho a ser indemnizados por las lesiones derivadas del funcionamiento de los servicios públicos, salvo:', array['En los casos de fuerza mayor o de daños que tengan el deber jurídico de soportar', 'Cuando el funcionamiento del servicio haya sido normal', 'Cuando el daño lo cause personal laboral', 'En los casos de caso fortuito, exclusivamente']::text[], 0, 'El artículo 32.1 reconoce el derecho por el funcionamiento «normal o anormal de los servicios públicos salvo en los casos de fuerza mayor o de daños que el particular tenga el deber jurídico de soportar de acuerdo con la Ley».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-032', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-033', (select id from leyes where slug = 'ley-40-2015'), '55.3', 'En la organización central de la Administración General del Estado, son órganos superiores:', array['Los Ministros y los Subsecretarios', 'Los Secretarios de Estado y los Secretarios generales', 'Los Ministros, los Secretarios de Estado y los Subsecretarios', 'Los Ministros y los Secretarios de Estado']::text[], 3, 'El artículo 55.3 enumera como «Órganos superiores: 1.º Los Ministros. 2.º Los Secretarios de Estado». Los Subsecretarios son órganos directivos.', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-033', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-034', (select id from leyes where slug = 'ley-40-2015'), '55.3', '¿Cuál de los siguientes NO es un órgano directivo de la organización central de la Administración General del Estado?', array['El Subsecretario', 'El Secretario general técnico', 'El Secretario de Estado', 'El Subdirector general']::text[], 2, 'El Secretario de Estado es un órgano superior. El artículo 55.3 incluye entre los órganos directivos a «1.º Los Subsecretarios y Secretarios generales. 2.º Los Secretarios generales técnicos y Directores generales. 3.º Los Subdirectores generales».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-034', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-035', (select id from leyes where slug = 'ley-40-2015'), '55.6', '¿Qué órganos superiores y directivos de la Administración General del Estado NO tienen la condición de alto cargo?', array['Los Directores generales', 'Los Subdirectores generales y asimilados', 'Los Secretarios generales técnicos', 'Los Subdelegados del Gobierno']::text[], 1, 'El artículo 55.6 atribuye la condición de alto cargo a los órganos superiores y directivos, «excepto los Subdirectores generales y asimilados».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
