insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-036', (select id from leyes where slug = 'ley-40-2015'), '57.3', 'El número, la denominación y el ámbito de competencia de los Ministerios y las Secretarías de Estado se establecen mediante:', array['Real Decreto del Presidente del Gobierno', 'Real Decreto acordado en Consejo de Ministros', 'Ley de las Cortes Generales', 'Orden del Ministro de Hacienda']::text[], 0, 'El artículo 57.3 dice que se establecen «mediante Real Decreto del Presidente del Gobierno».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
