insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-037', (select id from leyes where slug = 'ley-40-2015'), '66.2', 'Los Directores generales son nombrados y separados:', array['Por Orden del Ministro', 'Por Real Decreto del Presidente del Gobierno', 'Por resolución del Subsecretario', 'Por Real Decreto del Consejo de Ministros']::text[], 3, 'El artículo 66.2 establece que «serán nombrados y separados por Real Decreto del Consejo de Ministros, a propuesta del titular del Departamento o del Presidente del Gobierno».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
