insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-038', (select id from leyes where slug = 'ley-40-2015'), '67.2', 'Los Subdirectores generales son nombrados y cesados por:', array['El Consejo de Ministros, a propuesta del titular del Departamento', 'El Director general del que dependan, previa convocatoria pública', 'El Ministro, Secretario de Estado o Subsecretario del que dependan', 'El Presidente del Gobierno, a propuesta del Ministro correspondiente']::text[], 2, 'El artículo 67.2 dice que son nombrados y cesados «por el Ministro, Secretario de Estado o Subsecretario del que dependan».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
