insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-039', (select id from leyes where slug = 'ley-40-2015'), '63.1.f', '¿A qué órgano corresponde desempeñar la jefatura superior de todo el personal del Departamento ministerial?', array['Al Ministro', 'Al Subsecretario', 'Al Secretario general técnico', 'Al Secretario de Estado']::text[], 1, 'El artículo 63.1.f) atribuye a los Subsecretarios «Desempeñar la jefatura superior de todo el personal del Departamento».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-039', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-040', (select id from leyes where slug = 'ley-40-2015'), '72.3', 'Los Delegados del Gobierno en las Comunidades Autónomas son órganos directivos:', array['Con rango de Subsecretario, que dependen orgánicamente del Presidente del Gobierno', 'Con rango de Secretario de Estado, que dependen del Ministro del Interior', 'Con rango de Director general, que dependen del Presidente del Gobierno', 'Con rango de Secretario general, que dependen orgánicamente del Consejo de Ministros']::text[], 0, 'El artículo 72.3 dice que son «órganos directivos con rango de Subsecretario que dependen orgánicamente del Presidente del Gobierno» y funcionalmente del Ministerio competente por razón de la materia.', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-040', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-041', (select id from leyes where slug = 'ley-40-2015'), '84.1.a', '¿Cuál de las siguientes entidades NO es un organismo público vinculado o dependiente de la Administración General del Estado según el artículo 84.1.a)?', array['Los organismos autónomos', 'Las entidades públicas empresariales', 'Las agencias estatales', 'Las sociedades mercantiles estatales']::text[], 3, 'El artículo 84.1.a) clasifica los organismos públicos en «Organismos autónomos. 2. Entidades públicas empresariales. 3. Agencias estatales». Las sociedades mercantiles estatales forman parte del sector público institucional, pero no son organismos públicos (letra c).', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-041', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 8 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-001', (select id from leyes where slug = 'ley-40-2015'), '3.1', '¿Cuál de los siguientes NO figura entre los principios con los que, según el artículo 3.1 de la Ley 40/2015, actúan las Administraciones Públicas?', array['Jerarquía', 'Desconcentración', 'Coordinación', 'Autonomía']::text[], 3, 'El artículo 3.1 dice que las Administraciones «actúan de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación». La autonomía no figura en esa enumeración.', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-002', (select id from leyes where slug = 'ley-40-2015'), '3.1.e', 'Entre los principios que las Administraciones deben respetar en su actuación y relaciones, el artículo 3.1.e) de la Ley 40/2015 recoge:', array['Buena fe, seguridad jurídica y lealtad constitucional', 'Publicidad, confianza legítima y jerarquía normativa', 'Buena fe, confianza legítima y lealtad institucional', 'Legalidad, buena fe y cooperación internacional']::text[], 2, 'El artículo 3.1.e) enumera literalmente: «Buena fe, confianza legítima y lealtad institucional».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-002', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-003', (select id from leyes where slug = 'ley-40-2015'), '5.1', 'Según la Ley 40/2015, tienen la consideración de órganos administrativos las unidades administrativas:', array['Que tengan atribuidas funciones de coordinación interna, aunque carezcan de efectos frente a terceros', 'A las que se atribuyan funciones con efectos jurídicos frente a terceros, o cuya actuación tenga carácter preceptivo', 'Que estén dotadas de personalidad jurídica propia y de un presupuesto diferenciado', 'Que hayan sido creadas por una norma con rango de ley publicada en el boletín oficial']::text[], 1, 'El artículo 5.1 dice: «Tendrán la consideración de órganos administrativos las unidades administrativas a las que se les atribuyan funciones que tengan efectos jurídicos frente a terceros, o cuya actuación tenga carácter preceptivo».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-003', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-004', (select id from leyes where slug = 'ley-40-2015'), '5.3', '¿Cuál de los siguientes NO es uno de los requisitos mínimos que exige el artículo 5.3 de la Ley 40/2015 para crear un órgano administrativo?', array['El informe previo del Consejo de Estado', 'La determinación de su forma de integración y su dependencia jerárquica', 'La delimitación de sus funciones y competencias', 'La dotación de los créditos necesarios para su puesta en marcha y funcionamiento']::text[], 0, 'El artículo 5.3 exige «Determinación de su forma de integración en la Administración Pública de que se trate y su dependencia jerárquica», «Delimitación de sus funciones y competencias» y «Dotación de los créditos necesarios para su puesta en marcha y funcionamiento». No pide informe del Consejo de Estado.', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-004', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-005', (select id from leyes where slug = 'ley-40-2015'), '8.1', 'Según el artículo 8.1 de la Ley 40/2015, la competencia:', array['Es renunciable, siempre que lo autorice expresamente el superior jerárquico del órgano', 'Puede cederse libremente a otro órgano de la misma Administración mediante acuerdo', 'Es irrenunciable, salvo en los casos de encomienda de gestión y de delegación de firma', 'Es irrenunciable y se ejerce por los órganos que la tienen atribuida como propia, salvo delegación o avocación']::text[], 3, 'El artículo 8.1 dice: «La competencia es irrenunciable y se ejercerá por los órganos administrativos que la tengan atribuida como propia, salvo los casos de delegación o avocación».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-006', (select id from leyes where slug = 'ley-40-2015'), '8.1', 'La delegación de competencias, las encomiendas de gestión, la delegación de firma y la suplencia:', array['Suponen la transferencia de la titularidad de la competencia', 'Solo alteran la titularidad cuando se publican en el boletín oficial', 'No suponen alteración de la titularidad de la competencia', 'Alteran la titularidad, salvo la delegación de firma']::text[], 2, 'El artículo 8.1 establece que estas figuras «no suponen alteración de la titularidad de la competencia, aunque sí de los elementos determinantes de su ejercicio que en cada caso se prevén».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-006', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-007', (select id from leyes where slug = 'ley-40-2015'), '9.2.b', '¿Cuál de las siguientes competencias NO puede ser objeto de delegación según la Ley 40/2015?', array['La resolución de procedimientos sancionadores', 'La adopción de disposiciones de carácter general', 'La firma de convenios con otras Administraciones', 'La concesión de subvenciones']::text[], 1, 'El artículo 9.2 prohíbe delegar, entre otras, «La adopción de disposiciones de carácter general» (letra b).', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-007', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-008', (select id from leyes where slug = 'ley-40-2015'), '9.3', 'Las delegaciones de competencias y su revocación:', array['Deben publicarse en el boletín oficial que corresponda según la Administración del órgano delegante', 'Solo deben notificarse a los interesados en los procedimientos afectados por ellas', 'No necesitan publicarse para ser válidas; basta con comunicarlas al órgano delegado', 'Deben publicarse siempre en el BOE, sea cual sea la Administración del órgano delegante']::text[], 0, 'El artículo 9.3 dice: «Las delegaciones de competencias y su revocación deberán publicarse» en el BOE, en el de la comunidad autónoma o en el de la provincia, según la Administración a que pertenezca el órgano delegante.', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-009', (select id from leyes where slug = 'ley-40-2015'), '9.4', 'Las resoluciones administrativas adoptadas por delegación:', array['Se consideran dictadas por el órgano delegado', 'Se consideran dictadas por el superior común de delegante y delegado', 'No necesitan indicar que se han adoptado por delegación', 'Indican expresamente esta circunstancia y se consideran dictadas por el órgano delegante']::text[], 3, 'El artículo 9.4 establece que estas resoluciones «indicarán expresamente esta circunstancia y se considerarán dictadas por el órgano delegante».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-009', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-010', (select id from leyes where slug = 'ley-40-2015'), '9.5', '¿Pueden delegarse las competencias que se ejercen por delegación?', array['Sí, siempre que lo autorice el órgano delegante', 'Sí, con la aprobación del Ministro', 'No, salvo autorización expresa de una ley', 'No, en ningún caso']::text[], 2, 'El artículo 9.5 dice: «Salvo autorización expresa de una Ley, no podrán delegarse las competencias que se ejerzan por delegación».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-010', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-011', (select id from leyes where slug = 'ley-40-2015'), '9.6', 'Según el artículo 9.6 de la Ley 40/2015, la delegación de competencias:', array['Es irrevocable una vez publicada', 'Es revocable en cualquier momento por el órgano que la haya conferido', 'Solo puede revocarse transcurrido un año', 'Solo puede revocarla el superior jerárquico del delegante']::text[], 1, 'El artículo 9.6 establece: «La delegación será revocable en cualquier momento por el órgano que la haya conferido».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-011', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-012', (select id from leyes where slug = 'ley-40-2015'), '10.2', 'Contra el acuerdo de avocación:', array['No cabe recurso, aunque puede impugnarse en el que se interponga contra la resolución del procedimiento', 'Cabe recurso de alzada ante el superior jerárquico del órgano que acuerda la avocación', 'Cabe recurso potestativo de reposición ante el mismo órgano que acordó la avocación', 'Cabe recurso extraordinario de revisión, solo en los supuestos tasados por la ley']::text[], 0, 'El artículo 10.2 dice: «Contra el acuerdo de avocación no cabrá recurso, aunque podrá impugnarse en el que, en su caso, se interponga contra la resolución del procedimiento».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-013', (select id from leyes where slug = 'ley-40-2015'), '10.1', 'Cuando se delegan competencias en órganos no dependientes jerárquicamente, el conocimiento de un asunto puede avocarlo:', array['Cualquier órgano superior del delegado', 'El superior común de delegante y delegado', 'El Ministro del departamento del órgano delegado', 'Únicamente el órgano delegante']::text[], 3, 'El artículo 10.1 establece que, en esos supuestos, «el conocimiento de un asunto podrá ser avocado únicamente por el órgano delegante».', 3, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-014', (select id from leyes where slug = 'ley-40-2015'), '11.1', 'La encomienda de gestión tiene por objeto la realización de actividades:', array['De carácter normativo', 'De carácter sancionador', 'De carácter material o técnico', 'De carácter jurídico y resolutorio']::text[], 2, 'El artículo 11.1 dice que puede encomendarse «La realización de actividades de carácter material o técnico de la competencia de los órganos administrativos».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
