insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-015', (select id from leyes where slug = 'ley-40-2015'), '11.2', 'Respecto a la encomienda de gestión, es correcto que:', array['Supone la cesión de la titularidad de la competencia', 'No supone cesión de la titularidad de la competencia ni de los elementos sustantivos de su ejercicio', 'Transfiere al órgano encomendado la competencia para dictar los actos jurídicos', 'Puede tener por objeto prestaciones propias de los contratos del sector público']::text[], 1, 'El artículo 11.2 dice: «La encomienda de gestión no supone cesión de la titularidad de la competencia ni de los elementos sustantivos de su ejercicio».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
