insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-016', (select id from leyes where slug = 'ley-40-2015'), '12.2', 'Para la validez de la delegación de firma:', array['No es necesaria su publicación', 'Es necesaria su publicación en el BOE', 'Es necesaria la aprobación del superior jerárquico', 'Es necesaria la notificación a todos los interesados']::text[], 0, 'El artículo 12.2 dice: «La delegación de firma no alterará la competencia del órgano delegante y para su validez no será necesaria su publicación».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-016', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-017', (select id from leyes where slug = 'ley-40-2015'), '17.2', 'Para la válida constitución de un órgano colegiado se requiere la asistencia del Presidente y del Secretario, o de quienes les suplan, y de:', array['Dos tercios de sus miembros', 'La mayoría absoluta de sus miembros, sin contar al Presidente', 'Un tercio de sus miembros', 'La mitad, al menos, de sus miembros']::text[], 3, 'El artículo 17.2 exige la asistencia del Presidente y Secretario «y la de la mitad, al menos, de sus miembros».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'l40-017', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 11 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-018', (select id from leyes where slug = 'ley-40-2015'), '19.2.d', 'En los órganos colegiados de la Administración General del Estado, ¿a quién corresponde dirimir con su voto los empates?', array['Al Secretario', 'Al miembro de mayor antigüedad', 'Al Presidente', 'Al Vicepresidente']::text[], 2, 'El artículo 19.2 atribuye al Presidente, entre otras funciones, «Dirimir con su voto los empates, a efectos de adoptar acuerdos», salvo en los órganos del artículo 15.2.', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
