insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-019', (select id from leyes where slug = 'ley-40-2015'), '18.1', '¿Quién levanta el acta de cada sesión de un órgano colegiado?', array['El Presidente', 'El Secretario', 'El miembro de menor edad', 'El Vicepresidente']::text[], 1, 'El artículo 18.1 dice: «De cada sesión que celebre el órgano colegiado se levantará acta por el Secretario».', 1, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
