insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('l40-020', (select id from leyes where slug = 'ley-40-2015'), '18.2', 'El acta de cada sesión de un órgano colegiado puede aprobarse:', array['En la misma reunión o en la inmediata siguiente', 'Solo en la reunión inmediata siguiente', 'En el plazo de un mes desde la sesión', 'Solo en la misma reunión']::text[], 0, 'El artículo 18.2 dice: «El acta de cada sesión podrá aprobarse en la misma reunión o en la inmediata siguiente».', 2, '2024-08-22', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
