insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-001', (select id from leyes where slug = 'lo-3-2018'), '7.1', 'Según la LO 3/2018, el tratamiento de los datos de un menor puede fundarse en su consentimiento cuando sea:', array['Mayor de dieciséis años', 'Mayor de catorce años', 'Mayor de doce años', 'Mayor de dieciocho años']::text[], 1, 'El artículo 7.1 dice que el tratamiento de los datos de un menor solo podrá fundarse en su consentimiento «cuando sea mayor de catorce años».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
