insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-002', (select id from leyes where slug = 'lo-3-2018'), '7.2', 'El tratamiento de los datos de los menores de catorce años fundado en el consentimiento solo es lícito si consta:', array['El del titular de la patria potestad o tutela', 'El del propio menor ante notario', 'La autorización del Ministerio Fiscal', 'La autorización de la Agencia Española de Protección de Datos']::text[], 0, 'El artículo 7.2 dice que «solo será lícito si consta el del titular de la patria potestad o tutela».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
