insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-003', (select id from leyes where slug = 'lo-3-2018'), '1', 'Uno de los objetos de la LO 3/2018 es:', array['Transponer la Directiva 95/46/CE', 'Desarrollar el Convenio 108 del Consejo de Europa sin relación con el Reglamento europeo', 'Sustituir íntegramente al Reglamento (UE) 2016/679 en España', 'Adaptar el ordenamiento jurídico español al Reglamento (UE) 2016/679']::text[], 3, 'El artículo 1 dice que la ley tiene por objeto, entre otros, «adaptar el ordenamiento jurídico español al Reglamento (UE) 2016/679».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
