insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-004', (select id from leyes where slug = 'lo-3-2018'), '5.1', '¿Quiénes están sujetos al deber de confidencialidad según el artículo 5.1 de la LO 3/2018?', array['Solo el delegado de protección de datos designado por el responsable', 'Solo los responsables del tratamiento, pero no los encargados ni su personal', 'Los responsables y encargados del tratamiento y todas las personas que intervengan en cualquier fase de este', 'Solo el personal funcionario que trate datos en las Administraciones Públicas']::text[], 2, 'El artículo 5.1 dice que los responsables y encargados del tratamiento de datos «así como todas las personas que intervengan en cualquier fase de este estarán sujetas al deber de confidencialidad».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
