insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-005', (select id from leyes where slug = 'lo-3-2018'), '5.3', 'Las obligaciones de confidencialidad:', array['Terminan al finalizar la relación con el responsable', 'Se mantienen aun cuando haya finalizado la relación con el responsable o encargado', 'Duran dos años tras la finalización de la relación', 'Solo se mantienen si así se pacta por escrito']::text[], 1, 'El artículo 5.3 dice que estas obligaciones «se mantendrán aun cuando hubiese finalizado la relación del obligado con el responsable o encargado del tratamiento».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
