insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-006', (select id from leyes where slug = 'lo-3-2018'), '6.1', 'Según la LO 3/2018, el consentimiento del afectado es toda manifestación de voluntad:', array['Libre, específica, informada e inequívoca', 'Libre, expresa y por escrito', 'Informada y tácita', 'Libre, general y revocable']::text[], 0, 'El artículo 6.1 define el consentimiento como «toda manifestación de voluntad libre, específica, informada e inequívoca».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
