insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-007', (select id from leyes where slug = 'lo-3-2018'), '13.3', 'A efectos de la LO 3/2018, puede considerarse repetitivo el ejercicio del derecho de acceso más de una vez durante el plazo de:', array['Un año', 'Tres meses', 'Un mes', 'Seis meses']::text[], 3, 'El artículo 13.3 dice que podrá considerarse repetitivo «el ejercicio del derecho de acceso en más de una ocasión durante el plazo de seis meses», salvo causa legítima.', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
