insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-008', (select id from leyes where slug = 'lo-3-2018'), '22.3', 'Los datos obtenidos por videovigilancia con fines de seguridad deben suprimirse, como regla general, en el plazo máximo de:', array['Quince días desde su captación', 'Tres meses desde su captación', 'Un mes desde su captación', 'Una semana desde su captación']::text[], 2, 'El artículo 22.3 dice: «Los datos serán suprimidos en el plazo máximo de un mes desde su captación», salvo que deban conservarse para acreditar actos contra personas, bienes o instalaciones.', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
