insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-009', (select id from leyes where slug = 'lo-3-2018'), '22.1', 'Las personas físicas o jurídicas pueden tratar imágenes a través de sistemas de cámaras con la finalidad de:', array['Controlar los hábitos de consumo de los clientes en los establecimientos', 'Preservar la seguridad de las personas y bienes, así como de sus instalaciones', 'Elaborar perfiles comerciales de las personas que acceden a las instalaciones', 'Vigilar la vía pública sin limitación, como complemento de la policía']::text[], 1, 'El artículo 22.1 permite el tratamiento con la finalidad de «preservar la seguridad de las personas y bienes, así como de sus instalaciones».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
