insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-010', (select id from leyes where slug = 'lo-3-2018'), '44.1', 'La Agencia Española de Protección de Datos es:', array['Una autoridad administrativa independiente de ámbito estatal', 'Un organismo autónomo dependiente del Ministerio de Justicia', 'Una dirección general del Ministerio del Interior', 'Un órgano consultivo de las Cortes Generales']::text[], 0, 'El artículo 44.1 dice: «La Agencia Española de Protección de Datos es una autoridad administrativa independiente de ámbito estatal».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
