insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-011', (select id from leyes where slug = 'lo-3-2018'), '72.1', 'Según la LO 3/2018, las infracciones consideradas muy graves prescriben:', array['A los dos años', 'Al año', 'A los cinco años', 'A los tres años']::text[], 3, 'El artículo 72.1 dice: que se consideran muy graves «y prescribirán a los tres años» las infracciones que supongan una vulneración sustancial de los artículos mencionados en el artículo 83.5 del Reglamento.', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
