insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-014', (select id from leyes where slug = 'lo-3-2018'), '79', 'Según la LO 3/2018, los derechos y libertades consagrados en la Constitución y en los Tratados en que España es parte:', array['Son plenamente aplicables en Internet', 'Solo son aplicables en Internet si lo prevé una ley específica', 'Son aplicables en Internet con las limitaciones que fije el Gobierno', 'No son aplicables en Internet a los menores']::text[], 0, 'El artículo 79 dice que estos derechos y libertades «son plenamente aplicables en Internet».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
