insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-015', (select id from leyes where slug = 'lo-3-2018'), '88.1', '¿Quiénes tienen derecho a la desconexión digital según la LO 3/2018?', array['Solo los trabajadores del sector privado', 'Solo los empleados públicos', 'Solo los trabajadores a distancia', 'Los trabajadores y los empleados públicos']::text[], 3, 'El artículo 88.1 dice: «Los trabajadores y los empleados públicos tendrán derecho a la desconexión digital».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
