insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-016', (select id from leyes where slug = 'lo-3-2018'), '81.1', 'El derecho de acceso a Internet se reconoce:', array['Solo a los mayores de edad que tengan plena capacidad de obrar', 'Solo a los ciudadanos españoles y a los nacionales de la Unión Europea', 'A todos, independientemente de su condición personal, social, económica o geográfica', 'A quienes contraten un servicio de banda ancha con un operador autorizado']::text[], 2, 'El artículo 81.1 dice: «Todos tienen derecho a acceder a Internet independientemente de su condición personal, social, económica o geográfica».', 1, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
