insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-017', (select id from leyes where slug = 'lo-3-2018'), '87.1', 'Los trabajadores y empleados públicos tienen derecho a la protección de su intimidad en el uso de:', array['Sus dispositivos personales exclusivamente', 'Los dispositivos digitales puestos a su disposición por su empleador', 'Las redes sociales personales, exclusivamente', 'Los equipos de los clientes']::text[], 1, 'El artículo 87.1 reconoce el derecho «a la protección de su intimidad en el uso de los dispositivos digitales puestos a su disposición por su empleador».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
