insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-018', (select id from leyes where slug = 'lo-3-2018'), '9.1', 'El solo consentimiento del afectado NO basta para levantar la prohibición de tratar datos cuya finalidad principal sea identificar su:', array['Ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico', 'Domicilio, número de teléfono y dirección de correo electrónico', 'Nivel de estudios, titulaciones académicas y experiencia profesional', 'Situación laboral, empresa en la que trabaja y categoría profesional']::text[], 0, 'El artículo 9.1 dice que «el solo consentimiento del afectado no bastará para levantar la prohibición del tratamiento de datos cuya finalidad principal sea identificar su ideología, afiliación sindical, religión, orientación sexual, creencias u origen racial o étnico».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
