insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-021', (select id from leyes where slug = 'lo-3-2018'), '89.1', 'Los empleadores pueden tratar las imágenes obtenidas por cámaras para:', array['Vigilar las zonas de descanso, los vestuarios y los aseos del personal', 'Ejercer las funciones de control de los trabajadores o los empleados públicos', 'Grabar sonidos en cualquier lugar de trabajo sin ningún tipo de límite', 'Difundirlas con fines promocionales en las redes sociales de la empresa']::text[], 1, 'El artículo 89.1 dice que los empleadores podrán tratar las imágenes «para el ejercicio de las funciones de control de los trabajadores o los empleados públicos».', 2, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
