insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-022', (select id from leyes where slug = 'lo-3-2018'), '3.1', 'Las personas vinculadas al fallecido por razones familiares o de hecho, así como sus herederos, pueden dirigirse al responsable del tratamiento para:', array['Solicitar el acceso a los datos del fallecido y, en su caso, su rectificación o supresión', 'Solicitar una indemnización automática por el tratamiento de esos datos', 'Heredar la titularidad de los datos y cederlos libremente a terceros', 'Exigir la publicación de los datos del fallecido en un registro público']::text[], 0, 'El artículo 3.1 dice que podrán dirigirse al responsable o encargado del tratamiento «al objeto de solicitar el acceso a los datos personales de aquella y, en su caso, su rectificación o supresión» y, en su caso, su rectificación o supresión.', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
