insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-023', (select id from leyes where slug = 'lo-3-2018'), '48.5', 'El mandato de la Presidencia y de la Adjuntía de la Agencia Española de Protección de Datos dura:', array['Cuatro años, sin posibilidad de renovación para otro periodo', 'Seis años, sin posibilidad de renovación para otro periodo', 'Cinco años, sin posibilidad de renovación para otro periodo', 'Cinco años, renovable por otro periodo de igual duración']::text[], 3, 'El artículo 48.5 dice: «El mandato de la Presidencia y del Adjunto de la Agencia Española de Protección de Datos tiene una duración de cinco años y puede ser renovado para otro período de igual duración».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
