insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('pd-024', (select id from leyes where slug = 'lo-3-2018'), '78.1.a', 'Las sanciones por importe igual o inferior a 40.000 euros impuestas en aplicación de la LO 3/2018 prescriben en el plazo de:', array['Seis meses', 'Dos años', 'Un año', 'Tres años']::text[], 2, 'El artículo 78.1.a) dice: «Las sanciones por importe igual o inferior a 40.000 euros, prescriben en el plazo de un año».', 3, '2025-12-28', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
