insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-021', (select id from leyes where slug = 'trebep'), '48.a', 'Por fallecimiento de un familiar de primer grado de consanguinidad, ocurrido en la misma localidad, el funcionario tiene un permiso de:', array['Dos días hábiles', 'Cinco días hábiles', 'Cuatro días hábiles', 'Tres días hábiles']::text[], 3, 'El artículo 48.a) concede en caso de fallecimiento del cónyuge, pareja de hecho o familiar de primer grado «tres días hábiles cuando el suceso se produzca en la misma localidad», y cinco si es en distinta localidad.', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
