insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-022', (select id from leyes where slug = 'trebep'), '48.f', 'Por lactancia de un hijo menor de doce meses, el funcionario tiene derecho a:', array['Dos horas de ausencia diarias', 'Media hora de ausencia al inicio de la jornada', 'Una hora de ausencia del trabajo, que puede dividir en dos fracciones', 'Una hora de ausencia, sin posibilidad de dividirla']::text[], 2, 'El artículo 48.f) dice: «Por lactancia de un hijo menor de doce meses tendrán derecho a una hora de ausencia del trabajo que podrá dividir en dos fracciones».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
