insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-023', (select id from leyes where slug = 'trebep'), '48.i', 'Para atender el cuidado de un familiar de primer grado por enfermedad muy grave, el funcionario puede solicitar:', array['Una reducción de hasta el 50 % de la jornada, no retribuida, durante un máximo de tres meses', 'Una reducción de hasta el 50 % de la jornada, retribuida, durante un máximo de un mes', 'Un permiso retribuido de quince días', 'Una reducción de hasta un tercio de la jornada, retribuida, durante un máximo de dos meses']::text[], 1, 'El artículo 48.i) reconoce el derecho a solicitar «una reducción de hasta el cincuenta por ciento de la jornada laboral, con carácter retribuido, por razones de enfermedad muy grave y por el plazo máximo de un mes».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
