insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-024', (select id from leyes where slug = 'trebep'), '50.1', 'Las vacaciones anuales retribuidas de los funcionarios son de:', array['Veintidós días hábiles', 'Treinta días naturales', 'Veinticinco días hábiles', 'Un mes natural']::text[], 0, 'El artículo 50.1 reconoce «unas vacaciones retribuidas de veintidós días hábiles», o los días que correspondan proporcionalmente.', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
