insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-025', (select id from leyes where slug = 'trebep'), '50.1', 'A efectos de vacaciones de los funcionarios, los sábados:', array['Se consideran días hábiles', 'Se consideran hábiles solo en agosto', 'Se consideran hábiles si el funcionario trabaja en horario de mañana', 'No se consideran días hábiles, sin perjuicio de las adaptaciones para horarios especiales']::text[], 3, 'El artículo 50.1 dice: «no se considerarán como días hábiles los sábados, sin perjuicio de las adaptaciones que se establezcan para los horarios especiales».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
