insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-026', (select id from leyes where slug = 'trebep'), '52', '¿Cuál de los siguientes NO figura entre los principios del artículo 52 del TREBEP que inspiran el Código de Conducta?', array['Neutralidad', 'Ejemplaridad', 'Jerarquía', 'Austeridad']::text[], 2, 'El artículo 52 enumera, entre otros, «objetividad, integridad, neutralidad, responsabilidad, imparcialidad, confidencialidad, dedicación al servicio público, transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez». La jerarquía no figura entre ellos.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
