insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-027', (select id from leyes where slug = 'trebep'), '56.1.c', '¿Qué edad mínima se exige para participar en los procesos selectivos de acceso al empleo público?', array['Dieciocho años', 'Dieciséis años', 'Diecisiete años', 'Veintiún años']::text[], 1, 'El artículo 56.1.c) exige «Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
