insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-030', (select id from leyes where slug = 'trebep'), '60.2', '¿Quién puede formar parte de un órgano de selección?', array['Un funcionario interino', 'Una persona del personal eventual', 'Un funcionario de carrera', 'Una persona de designación política']::text[], 2, 'El artículo 60.2 dice: «El personal de elección o de designación política, los funcionarios interinos y el personal eventual no podrán formar parte de los órganos de selección».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
