insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-031', (select id from leyes where slug = 'trebep'), '63', '¿Cuál de las siguientes NO es causa de pérdida de la condición de funcionario de carrera?', array['La renuncia a la condición de funcionario', 'La jubilación parcial', 'La pérdida de la nacionalidad', 'La sanción firme de separación del servicio']::text[], 1, 'El artículo 63 incluye «La jubilación total del funcionario», no la parcial, junto con la renuncia, la pérdida de la nacionalidad, la separación firme y la inhabilitación firme.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-031', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-032', (select id from leyes where slug = 'trebep'), '64.2', 'No puede aceptarse la renuncia a la condición de funcionario cuando:', array['El funcionario está sujeto a expediente disciplinario', 'El funcionario tiene menos de cinco años de servicio', 'El funcionario está en excedencia voluntaria', 'La renuncia se presenta en los últimos tres meses del año']::text[], 0, 'El artículo 64.2 dice que no podrá aceptarse la renuncia «cuando el funcionario esté sujeto a expediente disciplinario» o se haya dictado auto de procesamiento o de apertura de juicio oral por delito.', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-032', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-033', (select id from leyes where slug = 'trebep'), '67.3', 'Según el artículo 67.3 del TREBEP, puede solicitarse la prolongación de la permanencia en el servicio activo como máximo hasta:', array['Los sesenta y siete años de edad', 'Los sesenta y ocho años de edad', 'Los setenta y dos años de edad', 'Los setenta años de edad']::text[], 3, 'El artículo 67.3 permite solicitar la prolongación «como máximo hasta que se cumpla setenta años de edad», en los términos de las leyes de Función Pública.', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
