insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-034', (select id from leyes where slug = 'trebep'), '76', '¿Qué título se exige para el acceso a los cuerpos o escalas del Subgrupo C2?', array['Bachiller o Técnico de Formación Profesional', 'Técnico Superior de Formación Profesional', 'Graduado en Educación Secundaria Obligatoria', 'Certificado de Estudios Primarios o equivalente']::text[], 2, 'El artículo 76 dice: «C2: Título de Graduado en Educación Secundaria Obligatoria».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
