insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-035', (select id from leyes where slug = 'trebep'), '85.1', '¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera recogida en el artículo 85.1 del TREBEP?', array['Servicios especiales', 'Expectativa de destino', 'Servicio en otras Administraciones Públicas', 'Suspensión de funciones']::text[], 1, 'El artículo 85.1 enumera: «a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
