insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-036', (select id from leyes where slug = 'trebep'), '89.2', 'Para obtener la excedencia voluntaria por interés particular, el TREBEP exige haber prestado servicios efectivos en cualquier Administración durante:', array['Un mínimo de cinco años inmediatamente anteriores', 'Un mínimo de tres años inmediatamente anteriores', 'Un mínimo de un año', 'Un mínimo de diez años']::text[], 0, 'El artículo 89.2 lo exige «durante un periodo mínimo de cinco años inmediatamente anteriores», aunque las leyes de Función Pública pueden fijar uno menor.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
