insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-037', (select id from leyes where slug = 'trebep'), '90.1', 'La suspensión de funciones determina la pérdida del puesto de trabajo cuando excede de:', array['Tres meses', 'Un año', 'Dos años', 'Seis meses']::text[], 3, 'El artículo 90.1 dice: «La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
