insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-038', (select id from leyes where slug = 'trebep'), '96.1.c', 'La sanción de suspensión firme de funciones tiene una duración máxima de:', array['Tres años', 'Cuatro años', 'Seis años', 'Un año']::text[], 2, 'El artículo 96.1.c) prevé la «Suspensión firme de funciones, o de empleo y sueldo en el caso del personal laboral, con una duración máxima de 6 años».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
