insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-039', (select id from leyes where slug = 'trebep'), '97.1', 'Según el TREBEP, las faltas leves prescriben:', array['Al año', 'A los seis meses', 'A los tres meses', 'A los dos años']::text[], 1, 'El artículo 97.1 dice: «Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
