insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-040', (select id from leyes where slug = 'trebep'), '95.2.c', '¿Cuál de las siguientes conductas es una falta muy grave según el artículo 95.2 del TREBEP?', array['El abandono del servicio', 'La falta de puntualidad', 'El descuido en el ejercicio de las funciones', 'La incorrección con el público']::text[], 0, 'El artículo 95.2.c) califica como falta muy grave «El abandono del servicio, así como no hacerse cargo voluntariamente de las tareas o funciones que tienen encomendadas».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
