insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-001', (select id from leyes where slug = 'trebep'), '8.2', 'Según el artículo 8.2 del TREBEP, ¿cuál de las siguientes NO es una de las clases de empleados públicos?', array['Funcionarios interinos', 'Personal laboral', 'Personal eventual', 'Personal directivo profesional']::text[], 3, 'El artículo 8.2 clasifica a los empleados públicos en «a) Funcionarios de carrera. b) Funcionarios interinos. c) Personal laboral, ya sea fijo, por tiempo indefinido o temporal. d) Personal eventual». El personal directivo se regula aparte, en el artículo 13.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-001', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-002', (select id from leyes where slug = 'trebep'), '8.1', 'Según el TREBEP, son empleados públicos:', array['Solo los funcionarios de carrera y los funcionarios interinos de cualquier Administración Pública', 'Quienes han superado un proceso selectivo basado en la igualdad, el mérito y la capacidad', 'Quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales', 'Quienes prestan servicios en el sector público, sean retribuidos o no, al servicio de la ciudadanía']::text[], 2, 'El artículo 8.1 dice: «Son empleados públicos quienes desempeñan funciones retribuidas en las Administraciones Públicas al servicio de los intereses generales».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
