insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-003', (select id from leyes where slug = 'trebep'), '9.1', 'Los funcionarios de carrera están vinculados a la Administración por una relación:', array['Laboral regulada por el Estatuto de los Trabajadores', 'Estatutaria regulada por el Derecho Administrativo', 'Contractual regulada por el Derecho Civil', 'Mixta, administrativa y laboral']::text[], 1, 'El artículo 9.1 dice que están vinculados «por una relación estatutaria regulada por el Derecho Administrativo para el desempeño de servicios profesionales retribuidos de carácter permanente».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
