insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-004', (select id from leyes where slug = 'trebep'), '9.2', 'El ejercicio de funciones que impliquen la participación en las potestades públicas o en la salvaguardia de los intereses generales corresponde:', array['Exclusivamente a los funcionarios públicos', 'A los empleados públicos de cualquier clase', 'Al personal laboral fijo y a los funcionarios', 'Al personal directivo profesional']::text[], 0, 'El artículo 9.2 dice que esas funciones «corresponden exclusivamente a los funcionarios públicos».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
