insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-005', (select id from leyes where slug = 'trebep'), '10.1.a', 'Un funcionario interino nombrado por la existencia de una plaza vacante puede ocuparla:', array['Por un máximo de dos años', 'Por un máximo de cinco años', 'Sin límite temporal hasta su cobertura', 'Por un máximo de tres años']::text[], 3, 'El artículo 10.1.a) permite nombrar interinos para plazas vacantes «por un máximo de tres años», en los términos del apartado 4.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-005', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-006', (select id from leyes where slug = 'trebep'), '10.1.d', 'Puede nombrarse funcionario interino por exceso o acumulación de tareas:', array['Por un plazo máximo de seis meses, dentro de un periodo de doce meses', 'Por un plazo máximo de doce meses, dentro de un periodo de dieciocho meses', 'Por un plazo máximo de nueve meses, dentro de un periodo de dieciocho meses', 'Por un plazo máximo de tres años']::text[], 2, 'El artículo 10.1.d) se refiere al exceso o acumulación de tareas «por plazo máximo de nueve meses, dentro de un periodo de dieciocho meses».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
