insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-007', (select id from leyes where slug = 'trebep'), '10.1.c', 'Los programas de carácter temporal que justifican el nombramiento de interinos no pueden durar más de:', array['Dos años, ampliables hasta seis meses más por las leyes de Función Pública', 'Tres años, ampliables hasta doce meses más por las leyes de Función Pública', 'Tres años, sin que las leyes de Función Pública puedan ampliar ese plazo', 'Cuatro años, ampliables hasta doce meses más por las leyes de Función Pública']::text[], 1, 'El artículo 10.1.c) dice que estos programas «no podrán tener una duración superior a tres años, ampliable hasta doce meses más por las leyes de Función Pública».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
