insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-008', (select id from leyes where slug = 'trebep'), '11.1', 'El personal laboral presta servicios retribuidos en las Administraciones Públicas:', array['En virtud de contrato de trabajo formalizado por escrito', 'En virtud de nombramiento legal', 'En virtud de nombramiento libre', 'En virtud de contrato administrativo de servicios']::text[], 0, 'El artículo 11.1 dice que es personal laboral el que presta servicios retribuidos «en virtud de contrato de trabajo formalizado por escrito».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-008', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-009', (select id from leyes where slug = 'trebep'), '12.1', 'El personal eventual realiza:', array['Funciones directivas profesionales', 'Funciones propias de funcionarios de carrera, con carácter temporal', 'Funciones de apoyo administrativo en los gabinetes', 'Solo funciones expresamente calificadas como de confianza o asesoramiento especial']::text[], 3, 'El artículo 12.1 dice que el personal eventual «sólo realiza funciones expresamente calificadas como de confianza o asesoramiento especial».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
