insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-010', (select id from leyes where slug = 'trebep'), '12.4', 'La condición de personal eventual:', array['Es mérito para el acceso a la Función Pública, pero no para la promoción interna', 'Es mérito solo para la promoción interna, nunca para el acceso a la Función Pública', 'No puede constituir mérito para el acceso a la Función Pública ni para la promoción interna', 'Da derecho a adquirir la condición de funcionario tras tres años de servicios']::text[], 2, 'El artículo 12.4 dice: «La condición de personal eventual no podrá constituir mérito para el acceso a la Función Pública o para la promoción interna».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
