insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-011', (select id from leyes where slug = 'trebep'), '12.3', 'El cese del personal eventual tiene lugar, en todo caso:', array['Al finalizar cada legislatura', 'Cuando cesa la autoridad a la que presta la función de confianza o asesoramiento', 'Cuando cumple cuatro años en el puesto', 'Cuando se cubre el puesto por un funcionario de carrera']::text[], 1, 'El artículo 12.3 dice que el cese tendrá lugar, en todo caso, «cuando se produzca el de la autoridad a la que se preste la función de confianza o asesoramiento».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
