insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-012', (select id from leyes where slug = 'trebep'), '13.4', 'Cuando el personal directivo profesional tiene la condición de personal laboral, está sometido a:', array['La relación laboral de carácter especial de alta dirección', 'El convenio colectivo único de la Administración General del Estado', 'El régimen general de los funcionarios de carrera', 'El régimen del personal eventual']::text[], 0, 'El artículo 13.4 dice que, en ese caso, «estará sometido a la relación laboral de carácter especial de alta dirección».', 3, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-012', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 13 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-013', (select id from leyes where slug = 'trebep'), '14.a', '¿Cuál de los siguientes es un derecho individual de los empleados públicos según el artículo 14 del TREBEP?', array['La libertad sindical', 'La negociación colectiva', 'El planteamiento de conflictos colectivos', 'La inamovilidad en la condición de funcionario de carrera']::text[], 3, 'El artículo 14.a) reconoce el derecho «A la inamovilidad en la condición de funcionario de carrera». Las otras opciones son derechos individuales ejercidos colectivamente (art. 15).', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-013', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 14 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-014', (select id from leyes where slug = 'trebep'), '15.c', '¿Cuál de los siguientes es un derecho individual que se ejerce de forma colectiva?', array['La formación continua y la actualización permanente de sus conocimientos', 'La progresión en la carrera profesional y la promoción interna', 'El ejercicio de la huelga, con mantenimiento de los servicios esenciales', 'La defensa jurídica por la Administración en los procedimientos judiciales']::text[], 2, 'El artículo 15.c) incluye el derecho «Al ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad».', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
