insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-015', (select id from leyes where slug = 'trebep'), '22.1', 'Las retribuciones de los funcionarios de carrera se clasifican en:', array['Fijas y variables', 'Básicas y complementarias', 'Ordinarias y extraordinarias', 'Básicas, complementarias y especiales']::text[], 1, 'El artículo 22.1 dice: «Las retribuciones de los funcionarios de carrera se clasifican en básicas y complementarias».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
