insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-016', (select id from leyes where slug = 'trebep'), '23', 'Las retribuciones básicas de los funcionarios:', array['Se fijan en la Ley de Presupuestos Generales del Estado', 'Las fija cada Administración en su relación de puestos de trabajo', 'Se fijan por acuerdo de la Mesa General de Negociación', 'Las fija el Ministerio de Hacienda por orden']::text[], 0, 'El artículo 23 dice que las retribuciones básicas «se fijan en la Ley de Presupuestos Generales del Estado» y están formadas por el sueldo y los trienios.', 2, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
