insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-017', (select id from leyes where slug = 'trebep'), '23.b', 'Los trienios consisten en una cantidad igual para cada Subgrupo o Grupo:', array['Por cada dos años de servicio', 'Por cada cinco años de servicio', 'Por cada tres años en el mismo puesto de trabajo', 'Por cada tres años de servicio']::text[], 3, 'El artículo 23.b) define los trienios como una cantidad igual para cada Subgrupo o Grupo «por cada tres años de servicio».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
