insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-018', (select id from leyes where slug = 'trebep'), '22.4', '¿Cuántas pagas extraordinarias al año perciben los funcionarios según el TREBEP?', array['Una', 'Tres', 'Dos', 'Catorce']::text[], 2, 'El artículo 22.4 dice: «Las pagas extraordinarias serán dos al año».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
