insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-019', (select id from leyes where slug = 'trebep'), '48.k', '¿Cuántos días de permiso por asuntos particulares al año reconoce el artículo 48 del TREBEP?', array['Cinco días', 'Seis días', 'Tres días', 'Ocho días']::text[], 1, 'El artículo 48.k) reconoce el permiso «Por asuntos particulares, seis días al año».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-019', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 14 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
insert into preguntas (id, ley_id, articulo, enunciado, opciones, correcta, explicacion, dificultad, fecha_version_boe, estado, actualizada_en) values ('trebep-020', (select id from leyes where slug = 'trebep'), '48.l', 'El permiso por matrimonio o constitución formalizada de pareja de hecho es de:', array['Quince días', 'Diez días', 'Veinte días', 'Quince días hábiles']::text[], 0, 'El artículo 48.l) fija el permiso «Por matrimonio o registro o constitución formalizada por documento público de pareja de hecho, quince días».', 1, '2025-07-31', 'validada', now()) on conflict (id) do update set ley_id = excluded.ley_id, articulo = excluded.articulo, enunciado = excluded.enunciado, opciones = excluded.opciones, correcta = excluded.correcta, explicacion = excluded.explicacion, dificultad = excluded.dificultad, fecha_version_boe = excluded.fecha_version_boe, estado = excluded.estado, actualizada_en = now();
insert into preguntas_oposiciones (pregunta_id, oposicion_id, tema_id) select 'trebep-020', o.id, te.id from oposiciones o join temas te on te.oposicion_id = o.id and te.numero = 14 where o.slug = 'aux-age' on conflict (pregunta_id, oposicion_id) do update set tema_id = excluded.tema_id;
